-- las-aventuras-de-tom-sawyer -- PARTE 1 de 5. Ejecuta las partes EN ORDEN.

-- La obra. Sin publicar todavia: asi no aparece a medio cargar.
insert into public.books
  (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values (
  'las-aventuras-de-tom-sawyer',
  'Las aventuras de Tom Sawyer',
  'Mark Twain',
  'Tom convence a medio pueblo de que pintar una valla es un privilegio. Luego ve un asesinato, se escapa a una isla y aparece en su propio funeral.',
  'novela', 0, 0, '{Clasico,Aventura}', false
)
on conflict (id) do nothing;

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  0,
  'Diabluras de Tom (1/3)',
  $lira$[{"type": "p", "text": "—Tom!"}, {"type": "p", "text": "Silencio."}, {"type": "p", "text": "—¡Tom!"}, {"type": "p", "text": "Silencio."}, {"type": "p", "text": "—¿Dónde se habrá metido ese muchacho? ¡Oye, Tom!"}, {"type": "p", "text": "Silencio."}, {"type": "p", "text": "La anciana se bajó las gafas y echó una ojeada a la estancia por encima de ellas; luego se las volvió a colocar y miró por debajo. Pocas veces o nunca miraba a través de las gafas para fijarse en un ser tan insignificante como un muchacho; eran un atributo de dignidad, el orgullo de su corazón, y estaban destinadas a «figurar», no a servir; del mismo modo hubiese podido mirar a través de un par de tapaderas de estufa. Se quedó perpleja un instante y luego dijo, no con fiereza, pero en voz bastante alta para que la oyeran los muebles:"}, {"type": "p", "text": "—Ya verás si te pongo la mano encima lo que…"}, {"type": "p", "text": "No concluyó la frase, ya que se había agachado para hurgar con la escoba por debajo de la cama, por lo que precisaba aliento para puntuar los escobazos. Solo resucitó al gato."}, {"type": "p", "text": "—No hay manera de atrapar a ese granuja."}, {"type": "p", "text": "Se dirigió hacia la puerta abierta, se detuvo allí y recorrió con la mirada las tomateras y las plantas de estramonio que constituían el jardín. Ni rastro de Tom. Entonces levantó la voz al tono exigido por la distancia y gritó:"}, {"type": "p", "text": "—¡Tooom!"}, {"type": "p", "text": "A su espalda oyó un ligero ruido y se volvió con el tiempo justo de atrapar a un niño pequeño por el faldón de la chaqueta y detener su huida."}, {"type": "p", "text": "—No sé cómo no se me había ocurrido que estarías en la despensa. ¿Qué hacías ahí dentro?"}, {"type": "p", "text": "—Nada."}, {"type": "p", "text": "—¡Nada! Mírate las manos. Y mírate la boca. ¿Qué son esas manchas?"}, {"type": "p", "text": "—No lo sé, tía."}, {"type": "p", "text": "—Bueno, yo sí que lo sé. Eso es mermelada. Te he dicho mil veces que si no dejabas en paz la mermelada te arrancaría la piel. Dame aquella vara."}, {"type": "p", "text": "La vara se agitó en el aire; el peligro era inminente."}, {"type": "p", "text": "—¡Mire a su espalda, tía!"}, {"type": "p", "text": "La anciana se dio la vuelta enseguida, asiéndose las faldas para apartarlas del peligro. Entretanto el muchacho se escapó, saltando por el alto vallado de estacas, y desapareció."}, {"type": "p", "text": "La tía Polly se quedó unos instantes perpleja y luego se echó a reír suavemente."}, {"type": "p", "text": "—Maldito chico, ¿es que no aprenderé nunca? ¿No me ha hecho ya bastantes jugarretas como esa para que espere atraparlo ahora? Pero un tonto viejo es el peor tonto que existe. Ya lo dice el refrán, «perro viejo no aprende trucos nuevos». Y, válgame el cielo, si cada día la treta es diferente, ¿cómo va una a saberla de antemano? Parece que sepa exactamente cuánto puede atormentarme sin hacerme perder la cabeza, y que si puede distraerme un minuto o hacerme reír, se me pasa el enfado y no puedo darle un cachete. No cumplo mi deber con el muchacho; esa es la verdad y bien lo sabe Dios. Ahorrar el palo hace al muchacho malo, como dice la Biblia. Estoy pecando y sufro por los dos, lo sé. El chico es de la piel de Barrabás, pero al fin y al cabo es el hijo de mi difunta hermana, pobrecilla, y no tengo valor para azotarle. Cada vez que le perdono me remuerde la conciencia, y cada vez que le pego se parte mi viejo corazón. Es cierto que hombre nacido de mujer tiene una vida corta y llena de tribulaciones, como dicen las Escrituras, y convengo en que así es. Esta tarde hará novillos y no me quedará otro remedio que hacerle trabajar mañana para castigarlo. Me duele hacerle trabajar los sábados mientras los demás muchachos tienen fiesta, pero él aborrece el trabajo más que nada en el mundo, y poco o mucho tengo que cumplir con mi deber o seré la ruina del chico."}, {"type": "p", "text": "Tom hizo novillos y se divirtió mucho. Volvió a casa justo a tiempo para ayudar a Jim, el muchacho de color, aserró la leña para el siguiente día y partió las teas antes de la cena; por lo menos llegó a tiempo para contarle sus hazañas a Jim, mientras este hacía las tres cuartas partes del trabajo. El hermano menor de Tom (o, mejor dicho, su hermanastro), Sid, había concluido ya su parte en la tarea (recoger las astillas). Sid era un niño tranquilo y de temperamento poco dado a las aventuras."}, {"type": "p", "text": "Mientras Tom cenaba, escamoteando azúcar cuando se le ofrecía la oportunidad, la tía Polly le hacía preguntas profundísimas y llenas de artificio para atraparlo en revelaciones perjudiciales. Como muchas otras almas candorosas, tenía la vanidad de creerse dotada de un talento especial para la diplomacia oscura y misteriosa, y le gustaba considerar sus sencillas tretas como maravillas de sagacidad."}, {"type": "p", "text": "—Tom, hacía bastante calor en la escuela, ¿verdad? —dijo."}]$lira$::jsonb,
  776
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  1,
  'Diabluras de Tom (2/3)',
  $lira$[{"type": "p", "text": "—Sí, señora."}, {"type": "p", "text": "—Mucho calor, ¿no?"}, {"type": "p", "text": "—Sí, señora."}, {"type": "p", "text": "—¿No te han dado ganas de darte un chapuzón, Tom?"}, {"type": "p", "text": "Un leve temor se apoderó de Tom, una especie de inquieta sospecha. Escrutó el rostro de la tía Polly, pero no descubrió nada. Entonces dijo:"}, {"type": "p", "text": "—No, señora; bueno, no muchas."}, {"type": "p", "text": "La anciana extendió la mano, palpó la camisa de Tom y dijo:"}, {"type": "p", "text": "—Pero ahora no tienes mucho calor. —Y se enorgulleció al pensar que había descubierto que la camisa estaba seca sin que nadie adivinara que esa era su intención. Pero Tom sabía, a despecho de su tía, de dónde soplaba el viento, así que se anticipó a la siguiente jugada."}, {"type": "p", "text": "—Algunos nos hemos mojado la cabeza bajo la bomba; la mía está húmeda aún. ¿Ve?"}, {"type": "p", "text": "La tía Polly se ofendió al pensar que había pasado por alto aquel detalle acusador, perdiéndose una pista. Entonces tuvo otra ocurrencia."}, {"type": "p", "text": "—Tom, supongo que no te has arrancado el cuello de la camisa de donde lo cosí para mojarte la cabeza, ¿verdad? Desabróchate la chaqueta."}, {"type": "p", "text": "La inquietud desapareció del rostro de Tom. Abrió la chaqueta. El cuello de la camisa estaba sólidamente cosido."}, {"type": "p", "text": "—¡Bribón! Bien, ya puedes marcharte. Estaba convencida de que habías hecho novillos y te habías ido a nadar. Te perdono, Tom. Creo que eres una especie de gato escarmentado, como dice el refrán, y mejor de lo que pareces… esta vez."}, {"type": "p", "text": "Le apesadumbraba el fracaso de su sagacidad, y al mismo tiempo estaba contenta de que Tom hubiese observado, por una vez, una conducta obediente."}, {"type": "p", "text": "Pero Sidney dijo:"}, {"type": "p", "text": "—Pues yo diría que usted le cosió el cuello con hilo blanco, y ahora es negro."}, {"type": "p", "text": "—¡Claro que lo cosí con hilo blanco! ¿Por qué lo dices? ¡Tom!"}, {"type": "p", "text": "Pero Tom no esperó el desenlace. Mientras escapaba hacia la puerta, dijo:"}, {"type": "p", "text": "—Siddy, de esta te acordarás."}, {"type": "p", "text": "Una vez que estuvo en lugar seguro, Tom examinó dos largas agujas que llevaba prendidas en las solapas de la chaqueta, enhebradas las dos, una con hilo blanco y la otra con negro."}, {"type": "p", "text": "—No se habría dado cuenta a no ser por Sid —dijo Tom—. ¡Caramba! Algunas veces cose con hilo blanco y otras con hilo negro. Ya podría decidirse por uno de los dos; yo no puedo estar siempre llevando la cuenta. En cuanto a Sid, ¡vaya si lo aporreo! ¡Recibirá su merecido!"}, {"type": "p", "text": "En el pueblo, Tom no pasaba por el muchacho modelo, pero conocía muy bien al chico que ostentaba ese título… y lo detestaba con toda su alma."}, {"type": "p", "text": "Al cabo de dos minutos, o menos aún, ya había olvidado todos sus infortunios. No porque sus infortunios fuesen para él un ápice menos duros y amargos de lo que son para un hombre los suyos propios, sino porque un nuevo y poderoso interés los dominó y los expulsó de su pensamiento, igual que los hombres se olvidan de las desgracias con la exaltación de nuevas empresas. El nuevo interés era una valiosa novedad en el arte de silbar que había aprendido recientemente de un negro, y Tom anhelaba practicarla sin estorbos. Consistía en un peculiar silbido de pájaro, una especie de líquido gorjeo, producido por el contacto de la lengua con el paladar a cortos intervalos, en mitad de la música; es probable que el lector lo recuerde si ha sido alguna vez muchacho. Con diligencia y atención logró perfeccionarlo enseguida, y entonces se encaminó calle abajo con la boca llena de armonías y el alma rebosante de gratitud. Sus sentimientos eran muy parecidos a los del astrónomo que ha descubierto un nuevo planeta, y en lo que respecta al placer intenso, profundo y puro, no cabe duda de que el muchacho aventajaba al astrónomo."}, {"type": "p", "text": "Las tardes de verano eran largas. No había oscurecido aún. Al poco rato Tom dejó de silbar. Un desconocido estaba ante él; un chico más alto que Tom. Un forastero de cualquier edad o sexo era una curiosidad impresionante en el sosegado pueblecillo de San Petersburgo. Además, el muchacho iba bien vestido, bien vestido en un día entre semana. Eso era sencillamente asombroso. Llevaba un gorro primoroso, y una chaqueta de tela azul abrochada, nueva y elegante, al igual que los pantalones. Calzaba zapatos, y era viernes. Hasta llevaba una corbata, un pedazo de cinta brillante. Tenía un aire de ciudad que le removía las entrañas a Tom. Cuanto más contemplaba Tom esa espléndida maravilla, más arrugaba la nariz y más ordinarias y vulgares le parecían sus propias prendas. Ninguno de los dos muchachos habló. Si el uno se movía, el otro también, pero solo de costado, en círculo; se mantenían cara a cara, mirándose a los ojos. Al fin Tom dijo:"}, {"type": "p", "text": "—Te puedo aporrear."}, {"type": "p", "text": "—Quisiera verlo."}, {"type": "p", "text": "—Pues lo puedo hacer."}]$lira$::jsonb,
  778
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  2,
  'Diabluras de Tom (3/3)',
  $lira$[{"type": "p", "text": "—No, no puedes."}, {"type": "p", "text": "—Sí que puedo."}, {"type": "p", "text": "—No puedes."}, {"type": "p", "text": "—Puedo."}, {"type": "p", "text": "—No puedes."}, {"type": "p", "text": "—Sí."}, {"type": "p", "text": "—No."}, {"type": "p", "text": "Hubo una pausa llena de inquietud. Entonces Tom dijo:"}, {"type": "p", "text": "—¿Cómo te llamas?"}, {"type": "p", "text": "—No es asunto tuyo."}, {"type": "p", "text": "—Pues me encantaría que lo fuera."}, {"type": "p", "text": "—¿Y por qué?"}, {"type": "p", "text": "—Cállate, o lo será."}, {"type": "p", "text": "—No me callo. Veamos."}, {"type": "p", "text": "—Vaya, te crees muy ingenioso, ¿eh? Si me da la gana, te puedo aporrear con una mano atada a la espalda."}, {"type": "p", "text": "—Bueno, ¿y por qué no te da la gana? Yo sí que puedo hacerlo."}, {"type": "p", "text": "—Pues lo haré, si sigues diciendo majaderías."}, {"type": "p", "text": "—Vaya, sí, he visto familias enteras en el mismo apuro."}, {"type": "p", "text": "—¡Qué sabio! Tú te crees alguien, ¿no? ¡Puf! ¡Qué sombrero!"}, {"type": "p", "text": "—Puedes abollarlo si no te gusta. Te desafío a que lo toques, y si te atreves recibirás lo tuyo."}, {"type": "p", "text": "—Eres un embustero."}, {"type": "p", "text": "—Y tú otro."}, {"type": "p", "text": "—Tú hablas mucho y no haces nada."}, {"type": "p", "text": "—¡Largo de aquí!"}, {"type": "p", "text": "—Oye, si sigues dándome la lata, te abro la cabeza con una piedra."}, {"type": "p", "text": "—¡Sí, claro que lo harás!"}, {"type": "p", "text": "—Sí que lo haré."}, {"type": "p", "text": "—Pues ¿por qué no lo haces? ¿Por qué solo dices que lo harás? ¿Por qué no te atreves? Porque tienes miedo."}, {"type": "p", "text": "—Yo no tengo miedo."}, {"type": "p", "text": "—Sí que tienes."}, {"type": "p", "text": "—No."}, {"type": "p", "text": "—Sí."}, {"type": "p", "text": "Otra pausa y más miradas y movimientos circulares, uno en torno al otro. No tardaron en encontrarse hombro contra hombro. Tom dijo:"}, {"type": "p", "text": "—¡Largo de aquí!"}, {"type": "p", "text": "—¡Vete tú!"}, {"type": "p", "text": "—No quiero."}, {"type": "p", "text": "—Yo tampoco."}, {"type": "p", "text": "Continuaron así, cada uno con un pie formando ángulo igual que un estribo, empujándose con toda el alma y fulminándose con miradas de odio. Pero ninguno de los dos conseguía ventaja. Después de forcejear hasta quedarse encendidos y sofocados, cedieron con cautela, y Tom dijo:"}, {"type": "p", "text": "—Eres un cobarde y un niño de teta. Se lo diré a mi hermano mayor, que puede hacerte papilla con el dedo meñique, y ¡ya verás cómo te deja!"}, {"type": "p", "text": "—¿Qué me importa a mí tu hermano mayor? Yo tengo un hermano que es mayor que él y, es más, puede arrojar por encima de esa valla al tuyo."}, {"type": "p", "text": "(Ambos hermanos eran imaginarios)."}, {"type": "p", "text": "—Eso es mentira."}, {"type": "p", "text": "Tom trazó una línea en el suelo con el dedo gordo del pie y dijo:"}, {"type": "p", "text": "—¡A ver si pisas la raya! Si lo haces te aporrearé hasta que no puedas tenerte en pie. Atrévete y recibirás de lo lindo."}, {"type": "p", "text": "El chico forastero pisó enseguida la línea y dijo:"}, {"type": "p", "text": "—Tú has dicho que lo harías; veámoslo ahora."}, {"type": "p", "text": "—No me busques las cosquillas y ándate con cuidado."}, {"type": "p", "text": "—Bien, has dicho que lo harías; ¿por qué no lo haces?"}, {"type": "p", "text": "—¡Voto va! Por dos centavos lo hago."}, {"type": "p", "text": "El forastero sacó dos monedas de cobre del bolsillo y las ofreció con escarnio. Tom las echó al suelo de un manotazo. Un instante después los dos muchachos rodaban por el suelo revolcándose en el polvo, agarrados como dos gatos, y durante un minuto se tiraron del pelo y de la ropa, se apuñaron y se arañaron la nariz, cubriéronse de polvo y de gloria. Luego la confusión adquirió forma y a través de la niebla de la batalla surgió Tom, sentado a horcajadas sobre su contrincante y aporreándolo con los puños."}, {"type": "p", "text": "—Di «me rindo» —dijo."}, {"type": "p", "text": "El otro muchacho solo se debatió para liberarse. Estaba llorando, sobre todo de rabia."}, {"type": "p", "text": "—Di «me rindo». —Y el aporreo prosiguió."}, {"type": "p", "text": "Al fin el forastero emitió un sofocado «¡Me rindo!», Tom dejó que se pusiera en pie y dijo:"}, {"type": "p", "text": "—Eso te enseñará. Más vale que la próxima vez mires con quién te metes."}, {"type": "p", "text": "El chico forastero se alejó sacudiéndose el polvo de la ropa y exhalando profundos suspiros; de vez en cuando se volvía, movía la cabeza y amenazaba a Tom con lo que le haría «la próxima vez que lo encontrase en la calle». Tom le contestó con algunas palabras mordaces y se alejó triunfalmente, pero apenas se había dado la vuelta, cuando el otro agarró una piedra, se la tiró a la espalda y luego se puso a correr como un antílope. Tom persiguió al traidor hasta su casa, y así descubrió dónde vivía. Se quedó ante la puerta de entrada durante un rato, desafiando al enemigo para que saliera, pero el enemigo solo le hizo muecas desde la ventana y declinó la invitación. Al final apareció la madre del enemigo y regañó a Tom, llamándolo muchacho malo, ordinario y perverso, y le ordenó que se fuera. Se alejó, pues, pero le dijo que el chico ya se las pagaría."}, {"type": "p", "text": "Aquella noche llegó bastante tarde a casa, y al entrar cautelosamente por la ventana descubrió una emboscada preparada por su tía; cuando esta vio el estado de sus ropas, la resolución de convertir la fiesta del sábado en cautiverio y dura labor se volvió firme e inamovible."}]$lira$::jsonb,
  774
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  3,
  'El glorioso pintor de brocha gorda (1/3)',
  $lira$[{"type": "p", "text": "Llegó la mañana del sábado, y el mundo veraniego era luminoso, suave y pletórico de vida. Había una canción en todos los corazones; y si el corazón era joven, la canción asomaba a los labios. Había alborozo en cada rostro y efluvios de primavera en todas partes. Los algarrobos estaban en flor y su fragancia llenaba el aire. La colina de Cardiff, más allá del pueblo y dominándolo, estaba verde por la vegetación, y se extendía a suficiente distancia como para parecer un país de ensueño, pacífico y atractivo. Tom apareció en la acera con un cubo de yeso diluido en agua y una brocha de largo mango. Examinó la valla y toda su alegría le abandonó, mientras una profunda melancolía se apoderaba de su espíritu. Treinta yardas de valla de nueve pies de altura. La vida le pareció vacía, y la existencia una pesada carga. Suspirando, mojó la brocha y la pasó a lo largo de la tabla superior; repitió la operación dos veces más, comparó el insignificante trazo blanqueado con el infinito continente de valla virgen y, desanimado, se sentó en un cajón de madera. Jim hizo su aparición saltando ante la entrada, con un pozal de hojalata, cantando Buffalo Girls. Acarrear agua desde la fuente municipal siempre había sido una tarea odiosa a los ojos de Tom, pero de repente no se lo pareció. Recordó que siempre había gente en la fuente. Chicos y chicas blancos, mulatos y negros siempre estaban allí esperando su turno, descansando, cambiando objetos, peleándose, luchando y alborotando. Y recordó que, aunque la fuente solo estaba a ciento cincuenta yardas de distancia, Jim no regresaba nunca con el cubo de agua hasta al cabo de una hora y, aun así, la mayoría de las veces alguien tenía que ir a buscarlo."}, {"type": "p", "text": "—Oye, Jim, yo iré a buscar el agua si tú blanqueas un poco —dijo Tom."}, {"type": "p", "text": "Jim sacudió la cabeza y contestó:"}, {"type": "p", "text": "—Imposible, amito Tom. La señora me ha dicho que fuera yo a buscar el agua y que no me parase con nadie. Ha dicho que suponía que el amito Tom me pediría que blanquease y ha añadido que no le hiciera caso, que me ocupara de mi trabajo, y ha dicho que ella ya se ocuparía del blanqueo."}, {"type": "p", "text": "—Vamos, no hagas caso de lo que ha dicho, Jim. Esa es su manera de hablar. Dame el pozal, no tardaré ni un minuto. Ella no se enterará."}, {"type": "p", "text": "—Ay, no me atrevo, amito. La señora me cortará el pescuezo. Vaya si lo hará."}, {"type": "p", "text": "—¡Ella! Si nunca pega a nadie; solo golpea la cabeza con el dedal, y eso no hace daño a nadie. Habla mucho, pero sus palabras no duelen, a no ser que se ponga a llorar. Jim, te daré algo estupendo. Te daré una canica blanca."}, {"type": "p", "text": "Jim empezó a vacilar."}, {"type": "p", "text": "—¡Una canica blanca, Jim! Una canica que siempre gana."}, {"type": "p", "text": "—Sí, es una canica maravillosa, ya lo veo. Pero, amito Tom, tengo muchísimo miedo de que la señora…"}, {"type": "p", "text": "—Y, además, si quieres te enseñaré el dedo herido del pie."}, {"type": "p", "text": "Jim solo era humano; semejante tentación era excesiva para él. Dejó el pozal en el suelo, cogió la bala blanca y se inclinó sobre el dedo del pie de Tom con indescriptible interés, mientras este último quitaba la venda. Un instante después Jim volaba calle abajo con el pozal y un zumbido a su espalda, Tom enjalbegaba con vigor, y la tía Polly se retiraba del campo de batalla con una zapatilla en la mano y la mirada triunfante."}, {"type": "p", "text": "Pero la energía de Tom no duró. Al pensar en los planes de diversión que tenía para aquel día, sus pesares se multiplicaron. No tardarían en aparecer los muchachos que tenían libertad y que se entregarían a toda clase de expediciones deliciosas. ¡Cómo se burlarían de él, al verlo trabajar! Este pensamiento lo abrasó como el fuego. Sacó todas sus riquezas terrenales y las examinó: fragmentos de juguetes, balas y desechos; lo suficiente, tal vez, para comprar un canje de trabajo, pero no lo bastante para comprar media hora de auténtica libertad. En consecuencia, se guardó los escasos tesoros en el bolsillo y abandonó la idea de intentar comprar a los muchachos. En ese sombrío y desesperado instante, ¡tuvo una ocurrencia repentina! Nada menos que una idea grandiosa y magnífica."}]$lira$::jsonb,
  716
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  4,
  'El glorioso pintor de brocha gorda (2/3)',
  $lira$[{"type": "p", "text": "Enarboló la brocha y se puso a trabajar con calma. Al cabo de poco hizo su aparición Ben Rogers, precisamente el muchacho, entre todos, cuyas burlas más había temido. Los pasos de Ben eran una mezcla de saltitos, brincos y botes, prueba suficiente de la ligereza de su corazón y de sus grandes perspectivas. Iba mordisqueando una manzana y a intervalos emitía un largo y melodioso chillido, seguido de un ding, dong, dong, ding, dong, dong en un tono grave, ya que se imaginaba que era un barco de vapor. Al acercarse, disminuyó la velocidad, se colocó en medio de la calle, se inclinó hacia estribor y orzó con pesadez, laboriosa pompa y meticulosidad, pues estaba personificando al Big Missouri y consideraba que tenía un calado de casi nueve pies de agua. Hacía al mismo tiempo el papel de barco, de capitán y el de las campanas del motor, de manera que tenía que imaginarse situado en el puente superior dando órdenes y ejecutándolas."}, {"type": "p", "text": "—¡Alto, contramaestre! Din, ding, ding."}, {"type": "p", "text": "Adelantó la proa y Ben se arrastró despacio hacia la acera."}, {"type": "p", "text": "—¡Marcha atrás! Din, ding, ding."}, {"type": "p", "text": "Estiró los brazos, que quedaron rígidos a los lados."}, {"type": "p", "text": "—¡Máquina a babor! ¡Ding, ding, ding! ¡Quiuu! ¡Chu, chu, chuuu! ¡Chuuu!"}, {"type": "p", "text": "Entretanto, su mano derecha describía majestuosos círculos, ya que representaba una rueda de cuarenta pies."}, {"type": "p", "text": "—¡Marcha atrás a babor! ¡Ding, ding, ding! ¡Chu, chu, chuuu!"}, {"type": "p", "text": "La mano izquierda empezó a describir círculos."}, {"type": "p", "text": "—¡Alto a estribor! ¡Ding, ding, ding! ¡Alto a babor! ¡Adelante a estribor! ¡Alto! ¡Virad con cuidado! ¡Ding, ding, ding! ¡Chu, chuuu! ¡Fuera esa relinga de gratil! Deprisa, muchachos. Atención, el cable de amarre, ¿qué esperáis vosotros ahí? ¡Sujetadlo al poste! ¡Acostad el muelle, ahora, venga! ¡Pare las máquinas, contramaestre! ¡Ding, ding, ding! ¡Chu, chu, chu! —decía dándole a las llaves de prueba. Tom seguía blanqueando; no prestaba la menor atención al vapor. Ben le observó un momento y dijo:"}, {"type": "p", "text": "—¡Hola! Tú eres el poste de amarre, ¿eh?"}, {"type": "p", "text": "Ninguna respuesta. Tom contemplaba sus últimos toques con una mirada de artista, luego daba otra suave pincelada con la brocha y volvía a contemplar el resultado. Ben se le acercó. Al ver la manzana, a Tom se le hizo agua la boca, pero continuó trabajando."}, {"type": "p", "text": "—Hola, chico, tienes que trabajar, ¿eh? —dijo Ben."}, {"type": "p", "text": "Tom se volvió repentinamente y dijo:"}, {"type": "p", "text": "—¡Ah! Eres tú, Ben. No te había visto."}, {"type": "p", "text": "—Oye, yo me voy a nadar. ¿No te gustaría venir? Pero tú prefieres trabajar, por supuesto, ¿verdad? Claro que sí."}, {"type": "p", "text": "Tom miró un instante al muchacho."}, {"type": "p", "text": "—¿A qué llamas tú trabajo? —preguntó."}, {"type": "p", "text": "—Ah, ¿eso no es trabajar?"}, {"type": "p", "text": "Tom prosiguió su tarea y contestó con indiferencia:"}, {"type": "p", "text": "—Tal vez lo sea, y tal vez no. En todo caso, a Tom Sawyer le gusta."}, {"type": "p", "text": "—Vamos, ¿me estás diciendo que te gusta?"}, {"type": "p", "text": "La brocha siguió moviéndose."}, {"type": "p", "text": "—¿Gustarme? No veo por qué no habría de gustarme. ¿Es que un chico tiene cada día la oportunidad de blanquear una valla?"}, {"type": "p", "text": "Eso le dio otro cariz al asunto. Ben cesó de mordisquear la manzana. Tom movía exquisitamente la brocha de un lado a otro, retrocedía para observar el efecto, añadía un brochazo aquí y allá y juzgaba de nuevo el efecto obtenido. Ben contemplaba cada movimiento con creciente interés y se sentía cautivado."}, {"type": "p", "text": "—Oye, Tom, déjame enjalbegar un poco."}, {"type": "p", "text": "Tom reflexionó, estuvo a punto de consentir, pero cambió de idea:"}, {"type": "p", "text": "—No, no, no es posible, Ben. La tía Polly es muy exigente con esta valla, con el trozo que da a la calle, ¿sabes?; pero si fuese la valla de la parte trasera, yo no tendría inconveniente, y ella tampoco. Sí, tiene una manía especial con esta parte de valla; ha de hacerse con mucho cuidado; creo que no hay un muchacho entre mil, quizá entre dos mil, que pueda blanquearla como a ella le gusta."}]$lira$::jsonb,
  630
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  5,
  'El glorioso pintor de brocha gorda (3/3)',
  $lira$[{"type": "p", "text": "—¿De veras? ¡Vamos, déjame probar! Solo un poco; yo te dejaría, si estuvieras en mi lugar, Tom."}, {"type": "p", "text": "—Ben, yo te dejaría blanquear encantado; pero la tía Polly… Jim quiso hacerlo, pero ella no le dejó; Sid quiso hacerlo y tampoco se lo permitió. ¿Comprendes ahora mi situación? Si empiezas a pintar esta valla y ocurre cualquier cosa…"}, {"type": "p", "text": "—No temas, tendré tanto cuidado como tú. Déjame probar, Tom. Oye, te daré el corazón de la manzana."}, {"type": "p", "text": "—Sí, pero… No, Ben, ahora no. Tengo miedo…"}, {"type": "p", "text": "—Te la daré toda."}, {"type": "p", "text": "Tom entregó la brocha con la preocupación pintada en el rostro pero con alegría en el corazón. Y mientras el antiguo vapor Big Missouri trabajaba y sudaba al sol, el artista retirado se sentaba sobre un barril, dejaba colgar las piernas, hincaba el diente en la manzana y planeaba la matanza de nuevos inocentes. No faltó material; iban apareciendo otros muchachos; venían a burlarse, pero se quedaban a blanquear. Cuando Ben estuvo rendido, Tom vendió el siguiente turno a Billy Fisher a cambio de una cometa en buen estado; y cuando terminó Billy, Johnny Miller adquirió los siguientes derechos por una rata muerta y un cordel con que hacerla voltear… y así sucesivamente, hora tras hora. Y al llegar a media tarde, el pobre muchacho de la mañana nadaba literalmente en la abundancia. Además de los objetos ya mencionados tenía doce canicas, un fragmento de cítara, un trozo de botella de cristal azul para mirar a través, un cañón hecho con un carrete, una llave que no podía abrir nada, un pedazo de yeso, un tapón de cristal de garrafa, un soldado de plomo, un par de renacuajos, seis cohetes, un gatito bizco, una manecilla de puerta, un collar de perro —pero sin el perro—, un mango de cuchillo, cuatro pedazos de corteza de naranja y un arruinado y viejo bastidor de ventana."}, {"type": "p", "text": "Tom se dijo que, a fin de cuentas, el mundo no era tan desagradable. Había descubierto, sin saberlo, una gran ley de la actividad humana, a saber: que para que un hombre o un muchacho codicie una cosa solo hace falta que la cosa sea difícil de alcanzar. Si Tom hubiera sido un gran filósofo lleno de sabiduría, como el autor de este libro, hubiese comprendido que el trabajo consiste en lo que el hombre se ve obligado a hacer, y que el juego consiste en lo que el hombre no se ve obligado a hacer. Y ello le hubiera ayudado a comprender por qué construir flores artificiales o atarearse en un molino de rueda es trabajo, mientras que jugar a bolos o escalar el Mont Blanc es pura diversión. En Inglaterra hay acaudalados caballeros que conducen carruajes de pasajeros de cuatro caballos, en trayectos diarios de veinte o treinta millas en verano, porque este privilegio les cuesta sumas considerables; pero si se les ofreciese una paga por el servicio, la diversión se convertiría en trabajo, y entonces renunciarían a ella."}, {"type": "p", "text": "El muchacho reflexionó unos instantes sobre el cambio sustancial que habían sufrido sus mundanas riquezas, y luego se encaminó al cuartel general para el informe."}]$lira$::jsonb,
  516
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  6,
  'Ocupaciones bélicas y amorosas (1/3)',
  $lira$[{"type": "p", "text": "Tom se presentó ante la tía Polly, que estaba sentada junto a la ventana abierta de una agradable sala de la parte trasera, que era una mezcla de dormitorio, comedor y biblioteca. El balsámico aire estival, la quietud llena de reposo, el perfume de las flores y el soñoliento zumbido de las abejas habían obrado su efecto, y la tía Polly estaba dando cabezadas sobre su labor de calceta, pues no tenía más compañía que el gato y este se le había dormido en el regazo. Como medida preventiva, se había colocado las gafas sobre su cabeza gris. Estaba tan segura de que Tom habría desertado hacía un buen rato que se maravilló al ver que se entregaba a ella de un modo tan audaz."}, {"type": "p", "text": "—¿Puedo ir a jugar ya, tía? —le preguntó."}, {"type": "p", "text": "—¿Qué dices? ¿Tan pronto? ¿Cuánto trabajo has hecho?"}, {"type": "p", "text": "—Está todo hecho, tía."}, {"type": "p", "text": "—Tom, no mientas, ya sabes que no puedo soportarlo."}, {"type": "p", "text": "—No miento, tía; está todo hecho."}, {"type": "p", "text": "La tía Polly concedió poco crédito a tal afirmación. Salió a verlo por sí misma; y ya le hubiese contentado encontrar un veinte por ciento de verdad en la declaración de Tom. Al ver toda la valla blanqueada, y no solo blanqueada, sino recubierta de varias capas, y con la añadidura de una franja blanca en el suelo, su asombro fue casi indescriptible."}, {"type": "p", "text": "—Jamás lo hubiera creído. No hay que darle vueltas; si te lo propones, sabes trabajar, Tom. —Y diluyó el cumplido añadiendo—: Aunque confieso que son rarísimas las ocasiones en que te lo propones. Bien, vete a jugar; pero no tardes una semana en volver, o habrá zurribanda."}, {"type": "p", "text": "Le impresionó tanto el esplendor de su proeza que se llevó a Tom a la despensa, eligió una manzana de las más hermosas y se la ofreció acompañada de una edificante disertación sobre el valor y el sabor que adquiere un regalo conseguido sin pecado y con virtuoso esfuerzo. Y mientras terminaba el discurso con un florido párrafo de las Escrituras, Tom escamoteó una torta de nueces."}, {"type": "p", "text": "Cuando salía dando saltos, vio a Sid que comenzaba a subir la escalera exterior que llevaba a las habitaciones traseras del segundo piso. Había grumos de tierra a mano, y en un abrir y cerrar de ojos el aire se llenó de ellos. Pasaban disparados en torno a Sid como una granizada, y antes de que la tía Polly pudiese reunir sus asombradas facultades y socorrerlo, seis o siete terrones habían alcanzado su objetivo y Tom había desaparecido ya al otro lado de la valla. Existía una puerta de entrada, pero por lo general Tom tenía demasiada prisa para usarla. A la sazón su alma rebosaba paz, ya que había saldado su cuenta pendiente con Sid respecto al asunto del hilo negro."}, {"type": "p", "text": "Tom bordeó el grupo de casas y se encaminó a una fangosa avenida que discurría por detrás del establo de las vacas de su tía. Poco después se encontraba a salvo de los peligros de captura y castigo, y se dirigía apresuradamente a la plaza mayor del pueblo, donde dos bandos de muchachos se habían reunido con fines bélicos, según una cita previa. Tom era general de uno de esos ejércitos y Joe Harper (su amigo más querido) era general del otro. Esos dos grandes estrategas no consentían pelear en persona —pues ello era más propio de sus subalternos—, por lo que se sentaban juntos sobre una pequeña eminencia y dirigían las operaciones mediante órdenes transmitidas por medio de edecanes. El ejército de Tom consiguió una gran victoria tras una batalla duramente disputada. Entonces se contaron los muertos, se cambiaron los prisioneros, se acordaron las condiciones para la próxima discordia y se fijó día para la batalla; luego se alinearon los ejércitos, partieron, y Tom se encaminó a su casa solo."}, {"type": "p", "text": "Al pasar por delante de la residencia de Jeff Thatcher, vio a una muchacha desconocida en el jardín, una deliciosa criatura de ojos azules y cabellos rubios peinados en dos largas trenzas, con una bata de verano y un pantalón con puntilla. El héroe recién coronado de laureles fue vencido sin disparar un tiro. Una tal Amy Lawrence se esfumó de su corazón y no dejó siquiera un recuerdo. Había creído amarla locamente, había considerado que su amor era adoración, y de pronto se dio cuenta de que solo era una pequeña debilidad evanescente. Había empleado meses en conquistarla; ella se había rendido hacía apenas una semana; Tom había sido el muchacho más feliz y más orgulloso del mundo durante siete únicos días y de repente, en un instante, Amy había desaparecido de su corazón como un forastero que termina su visita imprevista."}]$lira$::jsonb,
  773
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  7,
  'Ocupaciones bélicas y amorosas (2/3)',
  $lira$[{"type": "p", "text": "Admiró ese nuevo ángel a escondidas, hasta que vio que ella le había descubierto; entonces pretendió ignorar que ella estaba presente y comenzó a «exhibirse» en toda clase de absurdas acciones infantiles, a fin de ganar su admiración. Se entregó a esos grotescos disparates durante un rato; pero de repente, en mitad de unos peligrosos ejercicios gimnásticos, miró de soslayo y vio que la niña volvía hacia la casa. Tom se acercó a la valla y se apoyó en ella pesaroso, abrigando la esperanza de ver a la muchacha quedarse un ratito más. Ella se detuvo al subir los peldaños y se dirigió hacia la puerta. Tom exhaló un profundo suspiro cuando ella puso el pie en el umbral. Pero se le iluminó el rostro enseguida, al ver que la adorada tiraba un pensamiento por encima de la valla antes de desaparecer."}, {"type": "p", "text": "El muchacho echó a correr y dobló la esquina, deteniéndose a poca distancia de la flor; luego se protegió los ojos con la mano y se puso a mirar calle abajo como si hubiese descubierto algo de interés en aquella dirección. Poco después recogió una paja e intentó sostenerla sobre la nariz, con la cabeza inclinada hacia atrás, y mientras se movía de un lado a otro, con gran esfuerzo, se acercaba cada vez más al pensamiento; al fin su pie desnudo descansó sobre la flor, sus flexibles dedos se cerraron y, renqueando, se alejó con el tesoro y desapareció al doblar la esquina. Pero tan solo un minuto, el tiempo de encerrar la flor en el interior de la chaqueta, junto al corazón, o junto al estómago, pues no estaba muy versado en anatomía y tampoco era muy exigente."}, {"type": "p", "text": "Volvió y estuvo rondando la valla hasta que oscureció, «exhibiéndose» como antes, pero la muchacha no volvió a mostrarse, aunque Tom se consoló un poco pensando que entretanto ella había estado cerca de alguna ventana presenciando sus atenciones. Al final regresó a casa de mala gana, con su pobre cabeza llena de visiones."}, {"type": "p", "text": "Durante toda la cena se mostró tan animado que su tía se preguntó «qué demonio se le habría metido en el cuerpo». Recibió una buena reprimenda por los terrones lanzados a Sid, pero no pareció importarle gran cosa. Trató de robar azúcar ante las mismas narices de su tía y obtuvo un buen golpe en los nudillos."}, {"type": "p", "text": "—Tía, usted no pega a Sid cuando coge azúcar —dijo."}, {"type": "p", "text": "—Sid no da tantos quebraderos de cabeza como tú. Si no te vigilara, tendrías siempre las manos en la azucarera."}, {"type": "p", "text": "La tía Polly se dirigió a la cocina, y Sid, feliz en su inmunidad, se apoderó de la azucarera con una gloriosa jactancia que a Tom le pareció insoportable. Sin embargo, el recipiente le resbaló de los dedos, cayendo y rompiéndose en mil pedazos. Tom estaba extasiado. Era tal su arrobamiento que hasta se mordió la lengua y guardó silencio. Se dijo que no diría una palabra, ni siquiera cuando entrara la tía, sino que continuaría callado hasta que ella le preguntase quién había cometido el daño; y él se lo diría entonces, y nada habría comparable en el mundo como ver aquel dechado de perfecciones «atrapado». Era presa de tal exaltación que apenas pudo dominarse cuando entró la anciana y se quedó en pie ante el estropicio, descargando relámpagos de ira por encima de sus gafas. Tom dijo para sí: «¡Ahí viene!». Y un instante después rodaba por el suelo. La poderosa mano se alzaba ya para pegar de nuevo, cuando Tom exclamó:"}, {"type": "p", "text": "—¡Deténgase! ¿Por qué me zurra a mí, si ha sido Sid?"}, {"type": "p", "text": "La tía Polly se detuvo, perpleja, y Tom imploró con los ojos el bálsamo de la piedad. Pero cuando recobró el uso de la palabra, la tía Polly solo dijo:"}, {"type": "p", "text": "—De todos modos, no creo que haya sido inútil. Seguramente habrás hecho alguna otra desvergonzada travesura mientras no estaba aquí."}, {"type": "p", "text": "Entonces le remordió la conciencia y sintió el intenso deseo de decir algo amable, pero juzgó que equivaldría a confesar que se había equivocado, cosa prohibida por la disciplina. En consecuencia, guardó silencio y prosiguió sus tareas con el corazón apesadumbrado. Tom, enfurruñado en un rincón, exaltaba sus pesares. Sabía que la tía Polly, en el fondo de su corazón, estaba arrepentida, y la conciencia de ello le recompensaba tristemente. Pero no daría muestras de reconocimiento ni las aceptaría. Sabía que una afanosa mirada lo envolvía de vez en vez, a través de un velo de lágrimas, pero se negó a percatarse de ella."}, {"type": "p", "text": "Se imaginaba a sí mismo yaciendo en un lecho, enfermo de muerte, y a su tía inclinada sobre él implorando una breve palabra de perdón; pero él volvía el rostro hacia la pared y moría sin pronunciar aquella palabra. ¡Ah! ¿Cómo se sentiría ella, entonces? También imaginaba que lo traían del río muerto, con el ensortijado pelo mojado y el triste corazón inmóvil. Y la tía Polly se le echaba encima y de sus ojos caía una lluvia de lágrimas, y sus labios suplicaban a Dios que le devolviese al muchacho y prometían que nunca, nunca más volvería a ofenderlo. Pero él seguiría allí, frío, blanco e inerte, pobre víctima cuyos pesares habían encontrado fin. Exacerbó tanto sus sentimientos con esos patéticos sueños que tuvo que tragar saliva a menudo porque se atragantaba; y sus ojos nadaban en un mar de agua que rebosaba al parpadear, y descendía y goteaba desde la punta de la nariz. Y el cultivo de su dolor era tan voluptuoso para él que no pudo soportar la intrusión en el mismo de ninguna alegría mundana ni de ningún goce discordante; era demasiado sagrado para tales contactos; y por eso, poco después, cuando su prima Mary entró bailando de alegría al verse de nuevo en casa tras haber pasado una interminable semana en el campo, se levantó y salió entre nubes y tinieblas por una puerta, mientras ella traía cantos y luz de sol por la otra."}]$lira$::jsonb,
  992
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  8,
  'Ocupaciones bélicas y amorosas (3/3)',
  $lira$[{"type": "p", "text": "Deambuló lejos de los lugares que solían frecuentar los muchachos y buscó parajes desolados que armonizaran con su estado de ánimo. Una balsa de troncos en el río le pareció una invitación y, sentándose sobre el borde, contempló la tenebrosa extensión de agua, mientras deseaba ahogarse repentina e inconscientemente, sin pasar por el desagradable trámite inventado por la naturaleza. Entonces se acordó de la flor. La sacó, arrugada y marchita, y se acrecentó poderosamente su siniestra felicidad. Se preguntó si, cuando se enterara, ella le compadecería. ¿Lloraría y desearía tener derecho a echarle los brazos al cuello para consolarle? ¿O se apartaría de él fríamente como el resto del mundo hostil? Tal perspectiva le produjo tanta agonía y un dolor tan placentero que la cultivó en su pensamiento dándole vueltas y más vueltas y situándola bajo nuevas y variadas luces, hasta que la agotó. Al final se levantó con un suspiro y se alejó en la oscuridad."}, {"type": "p", "text": "A eso de las nueve y media o las diez pasó por la desierta calle en que vivía la Adorable Desconocida; se paró un momento; ningún sonido llegó a su atento oído; una vela proyectaba un opaco fulgor sobre la cortina de una ventana del segundo piso. ¿Estaba allí la sagrada presencia? Escaló la valla y se deslizó a escondidas entre las plantas hasta situarse bajo aquella ventana; la miró un buen rato con emoción; entonces se tendió en el suelo, allí mismo, boca arriba, y unió las manos sobre el pecho aguantando la pobre flor marchita. Y así hubiera querido morirse, a la intemperie, en un mundo frío, sin ningún abrigo sobre su desvalida cabeza, sin una mano amiga que le secara el sudor mortal de la frente, sin un rostro amado que se inclinara piadosamente sobre él cuando llegase el estertor de la agonía. Y así lo vería ella al asomarse a la ventana en la mañana alegre, y entonces… ¿derramaría una lágrima sobre su pobre cuerpo inerte, exhalaría un suspiro al ver aquella vida joven y brillante echada a perder y tan prematuramente tronchada?"}, {"type": "p", "text": "La ventana se abrió, la voz discordante de una criada profanó la sagrada quietud y un diluvio de agua empapó el cuerpo tumbado del mártir."}, {"type": "p", "text": "El remojado héroe se puso en pie de un salto exhalando un bufido. Un zumbido como de proyectil rasgó el aire mezclado con el murmullo de un juramento, siguió un ruido de cristales rotos, y una forma menuda y vaga saltó la valla y desapareció a toda prisa en las tinieblas."}, {"type": "p", "text": "Poco rato después, mientras Tom, desnudo ya para acostarse, examinaba su ropa empapada a la luz de una vela de sebo, Sid se despertó; pero si sintió el más ligero impulso de hacer «alusiones», lo pensó mejor y guardó silencio, pues había un no sé qué peligroso en la mirada de Tom."}, {"type": "p", "text": "Tom se acostó prescindiendo de la retahíla de las plegarias, y Sid tomó nota mentalmente de la omisión."}]$lira$::jsonb,
  490
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  9,
  'Exhibiciones en la escuela dominical (1/4)',
  $lira$[{"type": "p", "text": "El sol se levantó sobre un mundo tranquilo y resplandeció sobre el pacífico pueblecillo como una bendición. Una vez concluido el desayuno, la tía Polly encabezó las prácticas religiosas de la familia: empezaron con una plegaria compuesta de sólidas capas de citas bíblicas, unidas entre sí por una fina argamasa de originalidad; y desde la cima de las mismas leyó un torvo capítulo de la Ley de Moisés, como si se hallara en el mismísimo Sinaí."}, {"type": "p", "text": "Entonces Tom se ajustó el cinturón, por decirlo así, y se lanzó a la tarea de «aprender sus versículos». Sid había aprendido su lección unos días antes. Tom hizo acopio de todas sus energías para fijar en su memoria cinco versículos, y eligió una parte del sermón del monte, porque no encontró versículos más cortos. Al cabo de media hora Tom tenía una idea general bastante vaga de su lección, pero no pasaba de ahí, porque su mente atravesaba el campo entero del pensamiento humano y tenía las manos ocupadas en perturbadoras recreaciones. Mary cogió el libro para hacerle recitar, y Tom intentó abrirse paso a través de la niebla."}, {"type": "p", "text": "—Bienaventurados los… los…"}, {"type": "p", "text": "—Pobres…"}, {"type": "p", "text": "—Sí, pobres; bienaventurados los pobres… y… y…"}, {"type": "p", "text": "—En espíritu…"}, {"type": "p", "text": "—En espíritu; bienaventurados los pobres de espíritu, porque ellos… ellos…"}, {"type": "p", "text": "—De ellos…"}, {"type": "p", "text": "—Porque de ellos… Bienaventurados los pobres en espíritu, porque de ellos es el reino de los cielos. Bienaventurados los que lloran, porque ellos… ellos…"}, {"type": "p", "text": "—Re…"}, {"type": "p", "text": "—Porque ellos… ellos…"}, {"type": "h", "text": "—R, E, C, I…"}, {"type": "p", "text": "—Porque ellos erre, e, ce. ¡Ay, no sé qué es eso!"}, {"type": "p", "text": "—¡Recibirán!"}, {"type": "p", "text": "—Ah, ¡recibirán! Porque ellos recibirán… porque… llorarán… bienaventurados los que recibirán… los que… los que llorarán, porque ellos recibirán… ¿qué recibirán? ¿Por qué no me lo dices, Mary? ¿Por qué eres tan mezquina?"}, {"type": "p", "text": "—¡Ay, Tom, qué cabeza tienes! Si yo no quiero hacerte rabiar. No es esa mi intención. Debes volver a estudiarlo. No te desanimes, Tom, lo aprenderás, y si lo aprendes te daré una cosa muy bonita. Los buenos chicos deben estudiar."}, {"type": "p", "text": "—Está bien. Oye, ¿qué es, Mary?, dime qué es."}, {"type": "p", "text": "—No te preocupes, Tom. Ya sabes que si digo que es una cosa bonita, lo es."}, {"type": "p", "text": "—No lo dudo, Mary. Muy bien, lo estudiaré otra vez."}, {"type": "p", "text": "Y lo estudió otra vez, y bajo la doble presión de la oscuridad y de la futura ganancia lo hizo con tanto ímpetu que logró un triunfo magnífico. Mary le regaló un flamante cuchillo Barlow que valía doce centavos y medio; y la convulsión de dicha que le recorrió el cuerpo a Tom lo sacudió hasta los cimientos. A decir verdad, el cuchillo no cortaba nada, pero era un «auténtico» Barlow y eso encerraba una inconcebible grandiosidad, aunque si los muchachos del Oeste han pensado alguna vez que tal arma podía ser falsificada en propio menoscabo, es algo que permanece en el misterio y que tal vez no se descubra jamás. A Tom se le ocurrió hacer con él unas muescas en el aparador y se disponía a comenzar en el escritorio cuando fue exhortado a vestirse para asistir a la escuela dominical."}, {"type": "p", "text": "Mary le dio una jofaina de hojalata llena de agua y un pedazo de jabón, y Tom salió fuera y dejó la jofaina sobre un pequeño banco; entonces sumergió el jabón en el agua y lo dejó en el fondo; se subió las mangas de la camisa, vertió el agua en el suelo y luego entró en la cocina y comenzó a secarse la cara con mucho ahínco en la toalla que colgaba detrás de la puerta. Pero Mary le arrebató la toalla y dijo:"}, {"type": "p", "text": "—¿No te da vergüenza, Tom? No debes ser tan malo. El agua no te hará ningún daño."}, {"type": "p", "text": "Tom se quedó un poco desconcertado. Llenaron la jofaina de nuevo, y esta vez Tom permaneció ante ella un ratito, haciendo acopio de fuerzas; respiró hondo y comenzó. Al entrar luego en la cocina, con los ojos cerrados y buscando a tientas la toalla, un honroso testimonio de agua jabonosa le goteaba del rostro. Pero al levantar la cara de la toalla, se pudo comprobar que el lavado aún no era perfecto, pues el territorio limpio se detenía abruptamente ante la barbilla y las quijadas, igual que una careta; por debajo y más allá de esa línea se extendía una oscura porción de terreno virgen de riego hacia abajo por delante y hacia atrás en torno del cuello. Mary lo cogió de la mano y, cuando hubo terminado con él, Tom era un hombre y un hermano, sin distinción de color, y sus cabellos húmedos estaban primorosamente peinados y sus cortos rizos sometidos a un efecto general de exquisitez y simetría. (A hurtadillas Tom se aplastaba los rizos, con gran dificultad, y se los estiraba sobre la cabeza, ya que opinaba que los rizos eran afeminados y los suyos le llenaban la vida de amargura). Entonces Mary sacó un traje que solo había llevado los domingos durante dos años —lo llamaban simplemente su «otra ropa»—, cosa que nos indica la magnitud de su guardarropa. La muchacha «le dio los últimos toques» una vez que Tom se hubo vestido; le abrochó la pulcra chaqueta hasta debajo de la barbilla, dio vuelta por encima de los hombros al vasto cuello de la camisa, lo cepilló y lo coronó con el moteado sombrero de paja. Tom tenía un aspecto mucho mejor y más incómodo. Y su incomodidad era tan real como aparente; se sentía apretado con toda aquella ropa cuya limpieza lo atormentaba. Abrigaba la esperanza de que Mary se olvidara los zapatos, pero la esperanza feneció: los untó por completo de sebo, según la costumbre, y se los llevó a Tom. Aquello le sacó de sus casillas y dijo que siempre le obligaban a hacer lo que no le venía en gana. Pero Mary dijo persuasivamente:"}]$lira$::jsonb,
  963
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  10,
  'Exhibiciones en la escuela dominical (2/4)',
  $lira$[{"type": "p", "text": "—Por favor, Tom, sé un buen chico."}, {"type": "p", "text": "De modo que, refunfuñando, se calzó los zapatos. Mary no tardó en estar lista, y los tres niños se encaminaron hacia la escuela dominical, lugar que Tom aborrecía con toda su alma, pero que agradaba a Sid y a Mary."}, {"type": "p", "text": "La clase dominical duraba desde las nueve hasta las diez y media, y luego se celebraba el servicio religioso. Dos de los niños siempre se quedaban voluntariamente para oír el sermón, y el otro también se quedaba… por razones de más peso. Los bancos de la iglesia, de respaldo alto y sin tapizar, podían acoger a unas trescientas personas; el edificio era una construcción pequeña y sencilla, con una especie de cajón de madera de pino en la cima a guisa de campanario. Antes de entrar Tom retrocedió unos pasos y se acercó a un endomingado camarada."}, {"type": "p", "text": "—Oye, Billy, ¿tienes algún billete amarillo?"}, {"type": "p", "text": "—Sí."}, {"type": "p", "text": "—¿Cuánto quieres por él?"}, {"type": "p", "text": "—¿Cuánto das?"}, {"type": "p", "text": "—Un pedazo de caramelo y un anzuelo."}, {"type": "p", "text": "—Enséñamelos."}, {"type": "p", "text": "Tom se los enseñó. Fueron satisfactorios y la propiedad cambió de manos. Luego trocó un par de canicas blancas por tres billetes encarnados, y alguna otra insignificancia por un par de billetes azules. Acechó a otros muchachos a medida que llegaban, y continuó comprando billetes de varios colores durante diez o quince minutos más. Luego entró en la iglesia con un enjambre de chicos y chicas, aseados y bulliciosos, se dirigió a su sitio y entabló pelea con el primer muchacho que encontró a mano. El maestro, un hombre grave y entrado en años, intervino; luego se dio la vuelta un momento, y mientras tanto Tom le tiró del pelo al chico del banco contiguo, pero estaba absorto en su libro cuando el muchacho se volvió; poco después pinchó con un alfiler a otro chico para oírle exclamar «¡Uy!», y consiguió una nueva reprimenda del profesor. Todos los compañeros de Tom eran parecidos: inquietos, alborotadores y fastidiosos. Cuando les tocó recitar sus lecciones, ni uno sabía los versículos a la perfección, y tuvieron que apuntarles continuamente. No obstante, cuando acabo ese tormento, cada uno recibió su recompensa en billetes azules que llevaban un pasaje de la Escritura; cada billete azul era el premio por haber sabido dos versículos. Diez billetes azules equivalían a uno encarnado, y podían canjearse por este; diez billetes encarnados equivalían a uno amarillo; por diez billetes amarillos el superintendente entregaba al alumno una Biblia encuadernada con gran sencillez (valía cuarenta centavos en aquella venturosa época). ¿Cuántos de mis lectores habrían tenido la perseverancia y la aplicación de aprenderse de memoria dos mil versículos, aunque se tratara de una Biblia ilustrada por Doré? Y, no obstante, Mary había obtenido dos Biblias de esta manera —fue la paciente labor de dos años—, y un muchacho de parentesco alemán había ganado cuatro o cinco. Ese muchacho recitó una vez tres mil versículos sin parar; pero el esfuerzo de sus facultades mentales fue excesivo, y a partir de aquel día se convirtió en poco menos que un idiota, lamentable desgracia para la escuela, ya que en las grandes ocasiones, ante el público, el superintendente (como decía Tom) hacía salir siempre al muchacho para que «se disparase». Solo los alumnos mayores procuraban conservar sus billetes y continuaban la tediosa labor hasta obtener una Biblia, de modo que la entrega de uno de estos premios era un acontecimiento desacostumbrado y notable; el alumno triunfador adquiría ese día tanta grandeza y celebridad que el corazón de cada escolar se encendía con una ardiente emulación que a menudo duraba un par de semanas. Es posible que el estómago intelectual de Tom nunca hubiese sentido realmente hambre de tales premios, pero no cabe duda de que todo su ser había ansiado más de una vez la gloria y el esplendor que implicaban."}, {"type": "p", "text": "En el momento oportuno, el superintendente se colocó en el púlpito, con un libro de himnos cerrado en la mano y el dedo índice entre las hojas, y ordenó que le prestaran atención. Cuando un superintendente de escuela dominical hace su acostumbrado discursito, un libro de himnos en la mano es tan necesario como la inevitable hoja de música para el cantante que aparece en el escenario y canta una romanza en un concierto, aunque el porqué sea un misterio; pues el paciente no hace nunca alusión al libro de himnos ni a la hoja de música. Ese superintendente era una criatura flaca de treinta y cinco años, con una vistosa perilla y el pelo corto y encrespado; llevaba un altísimo cuello duro, cuyo extremo superior le llegaba casi a las orejas y cuyas agudas puntas se encorvaban hacia delante a la altura de las comisuras de los labios, un vallado que obligaba a una recta mirada hacia el frente, y a girar todo el cuerpo si precisaba una visión lateral; apuntalaba la barbilla sobre una corbata que era tan ancha y larga como un billete de banco y terminaba con un flequillo; las punteras de sus zapatos se erguían de manera abrupta, siguiendo la moda, como la punta de un esquí, efecto que los jóvenes producían paciente y laboriosamente sentándose horas enteras con los pies doblados contra la pared. El señor Walters era un hombre de semblante grave y de corazón muy sincero y honesto; y sentía tanta reverencia por las cosas y los lugares sagrados, y las separaba tanto de las cuestiones mundanas, que, inconscientemente, su voz en la escuela dominical había adquirido una entonación particular de la que carecía por completo los demás días de la semana. Comenzó de esta manera:"}]$lira$::jsonb,
  926
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  11,
  'Exhibiciones en la escuela dominical (3/4)',
  $lira$[{"type": "p", "text": "—Ahora, niños, quiero que estéis quietecitos en vuestro sitio, como sabéis hacer, y que me prestéis toda la atención durante un minuto o dos. Así, eso es. Así se portan los niños y las niñas buenos. Veo una niñita que está mirando por la ventana y me temo que se imagina que yo estoy ahí fuera, en alguna parte, acaso en lo alto de un árbol dando un discurso a los pajaritos. (Risitas laudatorias). Quiero deciros el bien que me hace ver tantas caritas limpias y brillantes reunidas en un lugar como este, aprendiendo a obrar bien y a ser buenos."}, {"type": "p", "text": "Y así sucesivamente. No es menester transcribir el resto del discurso. Es de un modelo que no cambia, de modo que nos es familiar a todos."}, {"type": "p", "text": "El último tercio del discurso fue malogrado por la reanudación de peleas y otras distracciones entre algunos de los chicos malos, y por los murmullos y el desasosiego que se extendía por todas partes, bañando incluso las bases de rocas tan sólidas e incorruptibles como Sid y Mary. Pero todos los ruidos cesaron repentinamente al callarse la voz del señor Walters, y la conclusión del discurso fue recibida con un estallido de silenciosa gratitud."}, {"type": "p", "text": "Gran parte de los murmullos había sido producida por un acontecimiento bastante raro, la entrada de visitas: el abogado Thatcher, acompañado de un anciano de aspecto muy débil; un elegante caballero de mediana edad, de majestuoso porte, con el pelo entrecano, y una dama muy distinguida que sin duda era la esposa de este último. La dama llevaba una niña de la mano. Tom había estado inquieto, lleno de enojo y de aflicción; además, le remordía la conciencia y no podía encontrar la mirada de Amy Lawrence ni soportar sus amorosos ojos. Pero en cuanto vio a la pequeña forastera se le encendió el espíritu de dicha en un instante. Al punto empezó a «exhibirse» con toda el alma —dando puñadas a los chicos, tirándoles de los pelos y haciendo muecas—, es decir, empleando todas las artes que parecían aptas para fascinar a una muchacha y ganar su aplauso. Su exaltación solo poseía una espina, el recuerdo de su humillación en el jardín de aquel ángel, y, cual dibujo en la arena, se borró bajo las olas de felicidad que le pasaron por encima."}, {"type": "p", "text": "Acomodaron a los visitantes en el sitio de honor, y en cuanto terminó el discurso del señor Walters, este los presentó a la escuela. El hombre de mediana edad resultó ser un personaje prodigioso, nada menos que el juez del condado, la más indiscutible y augusta creación que habían contemplado los niños, que se preguntaban de qué clase de material estaría hecho, y casi deseaban oírle rugir y a la vez temían que lo hiciese. Era de Constantinople, a doce millas de distancia, de manera que había viajado y visto mundo. Aquellos mismos ojos habían contemplado el edificio del Tribunal del condado, cuyo tejado era de hojalata, decían. El imponente silencio y las hileras de ojos fascinados atestiguaban el pasmo que inspiraban esas reflexiones. Se trataba del gran juez Thatcher, hermano del abogado local. Jeff Thatcher se adelantó inmediatamente para mostrar su intimidad con el grande hombre y ser envidiado por toda la escuela. De haberlos oído, le hubieran parecido música celestial estos murmullos:"}, {"type": "p", "text": "—Míralo, Jim. Está… acercándosele. ¡Oye, fíjate! Se van a estrechar las manos… Están estrechándose las manos. Diantre, ¿no te gustaría ser Jeff?"}, {"type": "p", "text": "El señor Walters comenzó a «exhibirse» con toda clase de ruidos y de actividades oficiales, dando órdenes, emitiendo opiniones, prodigando advertencias aquí y allá, dondequiera que hallaba un blanco propicio. El bibliotecario «se exhibió», corriendo de un lado para otro con los brazos llenos de libros y haciendo buena parte de la bulla y el alboroto con que alardea de autoridad un insecto. Las señoritas profesoras «se exhibían», inclinándose con dulzura sobre alumnos a los que antes habían apuñeado, alzando lindos dedos amonestadores a los niños malos y dando cachetes amorosos a los buenos. Los jóvenes maestros «se exhibían» con leves reprimendas y otras pequeñas muestras de autoridad y fina atención a la disciplina, y gran parte de los profesores, de uno y otro sexo, tenían algo que hacer en la biblioteca; y eran tareas que con frecuencia habían de repetirse dos y tres veces (con mucho disgusto aparente). Las niñas «se exhibían» de maneras variadas, y los chicos «se exhibían» con tal diligencia que las bolitas de papel y el murmullo de las riñas llenaban el aire. Y, dominándolo todo, allí estaba sentado el gran hombre, irradiando una mayestática sonrisa judicial sobre toda la casa, y calentándose al sol de su propia grandeza, pues también él, sin duda, estaba «exhibiéndose»."}, {"type": "p", "text": "Tan solo faltaba una cosa para completar el éxtasis del señor Walters: la oportunidad de entregar una Biblia de premio y mostrar un prodigio. Varios alumnos tenían algunos billetes amarillos, pero ninguno suficientes. El señor Walters había interrogado a los discípulos más destacados. En aquel instante hubiera dado el mundo entero para tener de nuevo al chico alemán con la cabeza en su sano juicio. Y en aquel preciso momento, cuando la esperanza ya estaba muerta, Tom Sawyer se presentó con nueve billetes amarillos, nueve encarnados y diez azules, y solicitó una Biblia. Aquello fue como un rayo rasgando un cielo claro. Walters no esperaba tal aplicación de tal fuente ni durante los próximos diez años. Pero no había que darle vueltas, allí estaban las pruebas indiscutibles, y nada se podía objetar. Por lo tanto, Tom fue izado al nivel de los elegidos con el juez, y la gran noticia se anunció desde el cuartel general. Fue la sorpresa más entontecedora de la década, y causó tanta sensación que el nuevo héroe quedó elevado a la altura del héroe judicial, y la escuela tuvo dos maravillas para contemplar en vez de una. A los chicos les roía la envidia, pero los que sufrían el dolor más amargo eran los que se daban cuenta, demasiado tarde, de que ellos mismos habían contribuido a tan odiado esplendor procurando billetes a Tom a cambio de las riquezas que este había amasado vendiendo los privilegios de enjalbegar. Estos se despreciaban por haber sido víctimas de un fraude vil, de una taimada serpiente oculta en la hierba."}]$lira$::jsonb,
  1044
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  12,
  'Exhibiciones en la escuela dominical (4/4)',
  $lira$[{"type": "p", "text": "El premio fue entregado a Tom con toda la efusión que el superintendente pudo derramar en tales circunstancias; pero al chorro efusivo le faltaba un poco de autenticidad, pues el instinto del pobre diablo le decía que allí había un misterio que acaso no soportase muy bien la luz; era sencillamente descabellado que ese muchacho hubiera almacenado dos mil gavillas de sabiduría bíblica, cuando una docena ya hubieran agotado, sin duda, su capacidad."}, {"type": "p", "text": "Amy Lawrence estaba orgullosa y contenta y trató de obligar a Tom a mirarle a la cara, pero él no quiso mirar. Amy se extrañó; luego sintió un ápice de inquietud; una oscura sospecha fluctuó en su mente; la niña observó; una mirada furtiva fue una clara revelación, y entonces se le partió el corazón, sintió celos y rabia, le asomaron lágrimas a los ojos y odió a todo el mundo. A Tom más que a nadie (pensaba ella). Tom fue presentado al Juez; pero se le trabó la lengua, casi perdió el aliento y el corazón le latió con fuerza, en parte, a causa de la pavorosa grandeza del hombre, pero, sobre todo, porque era el padre de ella. Le hubiese gustado arrodillarse y adorarlo si hubieran estado a oscuras. El Juez posó la mano sobre la cabeza de Tom, lo llamó buen hombrecito y le preguntó su nombre. El muchacho tartamudeó un instante y dijo al fin:"}, {"type": "p", "text": "—Tom."}, {"type": "p", "text": "—Oh, no, Tom no, sino…"}, {"type": "p", "text": "—Thomas."}, {"type": "p", "text": "—Ah, eso es. Ya suponía yo que sería más largo. Pero me atrevería a decir que aún tienes otro nombre y que vas a decírmelo, ¿no?"}, {"type": "p", "text": "—Dile al caballero tu apellido, Thomas —dijo Walters—, y di «señor». No debes olvidar los modales."}, {"type": "p", "text": "—Thomas Sawyer, señor."}, {"type": "p", "text": "—¡Eso es! A eso llamo yo ser buen chico. Buen hombrecito. Extraordinario, todo un hombrecito. Dos mil versículos es mucho, muchísimo, muchísimo. Y nunca te arrepentirás del tiempo empleado en aprenderlos; pues el saber es lo mejor que hay en el mundo; es lo que hace grandes hombres y hombres buenos; tú también serás un gran hombre y un hombre bueno algún día, Thomas, y entonces volverás la vista hacia el pasado y te dirás: «Todo lo debo a los privilegios de la escuela dominical de mi niñez, todo lo debo a mis queridos maestros que me enseñaron a aprender, todo lo debo al bondadoso superintendente que me animó, cuidó de mí, y me dio una hermosa Biblia, una espléndida y elegante Biblia para mi uso particular, todo lo debo a la recta educación». Eso es lo que dirás, Thomas Sawyer, y no querrías cambiar por dinero los dos mil versículos, ¡desde luego que no! Y ahora no te importará decirnos a mí y a esta señora algunas de las cosas que has aprendido, no, claro que no te importará, porque nosotros estamos orgullosos de los muchachos estudiosos. Vamos a ver, sin duda conoces los nombres de los doce discípulos. ¿Quieres decirnos los nombres de los primeros que fueron elegidos?"}, {"type": "p", "text": "Tom daba tirones a un botón de la chaqueta con aire asustado. Enrojeció y bajó los ojos. El corazón del señor Walters se encogió. Se dijo que no era posible que el muchacho contestara aquella sencilla pregunta. ¿Por qué lo interrogaba el Juez? No obstante, se creyó obligado a hablar y dijo:"}, {"type": "p", "text": "—Contesta al caballero, Thomas; no tengas miedo."}, {"type": "p", "text": "Tom no se decidía."}, {"type": "p", "text": "—Yo sé que a mí me lo dirás —dijo la dama."}, {"type": "p", "text": "—Los nombres de los dos primeros discípulos fueron…"}, {"type": "h", "text": "—¡David Y Goliat!"}, {"type": "p", "text": "Corramos un caritativo velo sobre el resto de la escena."}]$lira$::jsonb,
  589
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  13,
  'El escarabajo y su presa (1/3)',
  $lira$[{"type": "p", "text": "Alrededor de las diez y media comenzó a tañer la agrietada campana de la iglesia, y al cabo de poco empezó a reunirse la gente para el sermón matutino. Los niños de la escuela dominical se distribuyeron por el recinto y ocuparon los bancos con sus familiares, a fin de estar bajo custodia. Llegó la tía Polly, y Tom, Sid y Mary se sentaron con ella; colocaron a Tom junto al pasillo para alejarlo todo lo posible de la ventana abierta y de las seductoras escenas estivales del exterior. La multitud desfilaba por los pasillos: el anciano y menesteroso administrador de correos, que había conocido días mejores; el alcalde y su esposa, porque en el pueblo tenían alcalde, entre otras bagatelas; el juez de paz; la viuda Douglas, una cuarentona rubia y elegante, acomodada, alma buena y generosa, cuya casa en la colina era la única mansión del pueblo, la persona más hospitalaria y pródiga en cuestión de fiestas de que podía ufanarse San Petersburgo; el encorvado y venerable antiguo alcalde y la señora Ward; el abogado Riverson, el nuevo notable de lejos; luego la belleza del pueblo, seguida por un ejército de atractivas jovencitas vestidas de linón y emperejiladas con cintas; luego todos los jóvenes empleados de la ciudad en comitiva, pues habían estado en el vestíbulo chupando el puño del bastón y sonriendo afectadamente, formando un muro circular de admiradores, hasta que la última muchacha hubo entrado en la iglesia; y por último llegó el Chico Modelo, Willie Mufferson, cuidando de su madre con tanto esmero como si fuese un objeto de fino cristal. Siempre llevaba a su madre a la iglesia y era el orgullo de todas las matronas. Todos los muchachos lo odiaban por ser tan bueno. Y, además, se lo habían presentado como modelo demasiadas veces. El pañuelo colgaba de su bolsillo, como era costumbre los domingos, con estudiado desaliño. Tom no tenía pañuelo y juzgaba ridículos a los muchachos que lo llevaban."}, {"type": "p", "text": "Una vez reunida toda la congregación, la campana tañó una vez más, avisando a los rezagados, y entonces una solemne quietud invadió la iglesia, solo interrumpida por las risitas y los murmullos del coro en la galería. El coro siempre reía y murmuraba durante todo el servicio. Una vez hubo un coro de iglesia que tenía educación, pero no recuerdo dónde. Hace muchísimos años y apenas me acuerdo de ningún detalle, pero creo que era en algún país extranjero."}, {"type": "p", "text": "El ministro señaló el himno y lo leyó con deleite, en un estilo peculiar que era muy admirado en aquella parte del país. Su voz empezaba en un medio tono y ascendía con fuerza hasta alcanzar un punto determinado, allí acentuaba con énfasis la palabra más alta y entonces descendía vertiginosamente como desde un trampolín:"}, {"type": "p", "text": "¿Me han de llevar al cielo sobre florido lecho acomodado,"}, {"type": "p", "text": "cuando otros, por el premio, luchan, surcando el mar ensangrentado?"}, {"type": "p", "text": "Se lo consideraba un lector maravilloso. En las reuniones de sociedad le rogaban siempre que leyera versos; y al concluir la lectura las damas alzaban las manos y las dejaban caer sin fuerza sobre la falda, entornaban los ojos y sacudían la cabeza, como diciendo: «No hay palabras para expresarlo; es demasiado hermoso, demasiado hermoso para esta tierra mortal»."}, {"type": "p", "text": "Una vez cantado el himno, el reverendo Sprague se transformó en una tablilla de avisos y leyó «notas» de reuniones, sociedades y otras cosas hasta dar la sensación de que la lista se alargaría hasta la hecatombe del día del Juicio Final; una rara costumbre que aún se mantiene en Estados Unidos, hasta en las ciudades e incluso en esta época de abundantes periódicos. A menudo, cuanto menos puede justificarse una costumbre tradicional, más difícil resulta desembarazarse de ella."}, {"type": "p", "text": "Luego el ministro rezó. Fue una generosa plegaria muy detallada; oró por la iglesia y por los niños que estaban en la iglesia; por las demás iglesias del pueblo; por el mismo pueblo; por el condado; por el estado, por los funcionarios del estado; por Estados Unidos; por las iglesias de Estados Unidos; por el presidente; por los funcionarios del gobierno; por los infelices marineros que navegaban en mares procelosos; por los millones de oprimidos que gimen bajo el yugo de las monarquías europeas y los despotismos orientales; por los que, habiendo recibido la luz y la buena nueva, no tenían, con todo, ojos para ver ni orejas para oír; por los paganos de las islas lejanas perdidas en el mar; y acabó suplicando que las palabras que iba a decir hallasen gracia y favor, y fuesen simiente sembrada en tierra fértil que produjese a su tiempo una grata cosecha de bien. Amén."}]$lira$::jsonb,
  773
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  14,
  'El escarabajo y su presa (2/3)',
  $lira$[{"type": "p", "text": "Se oyó un murmullo de ropas, y la gente que estaba en pie se sentó. El héroe de esta historia no se divertía con la plegaria; apenas la soportaba, si es que llegaba a eso siquiera. Estaba inquieto; inconscientemente llevaba la cuenta de los detalles de la plegaria, porque si bien no escuchaba, conocía el terreno de antiguo y la ruta que solía seguir el clérigo, y cuando intercalaba algún nuevo detalle, su oído lo descubría y toda su naturaleza se resentía; Tom juzgaba las añadiduras una traición. En mitad de la plegaria una mosca se posó en el respaldo del banco que tenía enfrente, y para su espíritu fue una tortura ver cómo se frotaba las manos con calma, se rodeaba la cabeza con los brazos y la restregaba con tanto vigor que parecía separarla casi del cuerpo, mientras mostraba el hilillo sutil del cuello; la vio rascarse las alas con las patitas traseras y alisarlas contra el cuerpo como si fueran los faldones de una casaca; la observó llevar a cabo esas operaciones sin inmutarse, como si supiese que estaba perfectamente a salvo. Y bien que lo estaba; pues por violento que fuese el prurito de las manos de Tom, no osaban atrapar la mosca, al creer que su alma habría sido destruida al instante de haber realizado semejante acción en el decurso de la plegaria. Pero con la frase final, la mano comenzó a encorvársele y a deslizarse furtivamente, y en el instante en que se dijo «Amén» la mosca era prisionera de guerra. La tía Polly lo descubrió y se la hizo soltar."}, {"type": "p", "text": "El ministro inició su sermón y, con la monotonía de un abejorro zumbador, desarrolló un argumento tan prosaico que al poco rato muchas personas estaban dando cabezadas. Sin embargo, era un argumento que trataba del fuego ilimitado y del azufre y reducía a los predestinados a la gloria a un número tan reducido que su salvación casi no valía la pena. Tom contaba las páginas del sermón; al salir de la iglesia siempre sabía el número de páginas leídas, pero raramente se enteraba de otra cosa. No obstante, esta vez llegó a interesarse de veras durante un breve rato. El ministro hacía una grandiosa y conmovedora descripción de la reunión de las huestes humanas en el milenario, cuando el león y el cordero yacerían juntos y un niñito los conduciría. Pero la emoción patética y la aleccionadora moral del gran espectáculo se perdían para el muchacho; este solo pensaba en la insigne grandeza del principal protagonista ante las naciones expectantes; se le iluminó el rostro ante la idea y se dijo que le gustaría ser aquel niño, siempre que el león fuera manso."}, {"type": "p", "text": "Luego volvió a su desasosiego anterior, mientras se reanudaba el árido argumento. Al cabo de poco se acordó de un tesoro que tenía y lo sacó. Era un formidable escarabajo negro con unas quijadas enormes; una «chinche con tenazas», lo llamaba él. Estaba encerrado en una caja de cápsulas. Lo primero que hizo el escarabajo fue agarrársele al dedo. Siguió un lógico papirotazo, el escarabajo rodó al pasillo quedando allí patas arriba, y el dedo herido se metió en la boca del muchacho. El escarabajo yacía en el suelo moviendo desesperadamente las patas, incapaz de darse la vuelta. Tom lo contemplaba y ansiaba cogerlo, pero el animalillo estaba a salvo, fuera de su alcance. Otras personas a quienes no interesaba el sermón encontraron alivio en el escarabajo y también se pusieron a observarlo. Poco después hizo su aparición un errante perro de aguas, con el corazón entristecido, amodorrado por la blandura y la calma estivales, abrumado por el cautiverio y suspirando por un cambio. Vio el escarabajo; el caído rabo se alzó y osciló. Vigiló la presa; dio una vuelta a su alrededor; lo olió desde una segura distancia; dio otra vuelta; se envalentonó y olfateó más cerca; entonces levantó el hocico y dio un cauteloso zarpazo al insecto, sin tocarlo; le dio otro y otro; comenzó a gozar de la diversión; se encogió hasta el estómago con el escarabajo entre las garras, y prosiguió sus experimentos; al final se cansó y se quedó indiferente y abstraído. Meneó la cabeza y bajó el hocico despacio y tocó el enemigo, que se aferró a él. Se oyó un gruñido doloroso, la cabeza del perro se movió con violencia y el escarabajo cayó a un par de yardas de distancia y, una vez más, se quedó patas arriba. Los espectadores vecinos se estremecieron con una dulce alegría interna, varios rostros se ocultaron tras abanicos y pañuelos, y Tom fue completamente feliz. El perro ofrecía un aspecto de bobo y es probable que se diera cuenta de ello; pero en su corazón anidaba el resentimiento y tenía ansias de venganza. Se acercó, pues, al escarabajo, iniciando otra vez un cauto ataque; saltando sobre él desde cada punto de un círculo, cayendo con las patas delanteras a una pulgada del insecto, dando mordiscos aún más cercanos, y sacudiendo la cabeza hasta que las orejas le vibraron de nuevo. No tardó en fatigarse otra vez e intentó divertirse con una mosca, pero no encontró alivio; persiguió dando vueltas a una hormiga, con el hocico pegado al suelo, pero aquello lo hastió enseguida; bostezó, suspiró, se olvidó por completo del escarabajo y se sentó encima de él. Entonces se oyó un desgarrador alarido de agonía y el can enfiló el pasillo a toda prisa; los alaridos continuaron y la carrera del perro también; cruzó el recinto frente al altar; descendió por el otro pasillo; cruzó ante las puertas; aulló al encontrarse en la última etapa; su angustia creció a medida que avanzaba, hasta que al poco rato no fue más que un lanudo cometa moviéndose en su órbita con el fulgor y la velocidad de la luz. Por último, la frenética víctima desvió su carrera y saltó al regazo de su dueño; este lo arrojó por la ventana y la voz del infortunio se debilitó enseguida hasta morir en la lejanía."}]$lira$::jsonb,
  1005
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  15,
  'El escarabajo y su presa (3/3)',
  $lira$[{"type": "p", "text": "Todos los fieles tenían la cara enrojecida y sofocada de reprimir la risa, y el sermón había llegado a una mortal estancación. El discurso se reanudó al cabo de poco, pero se deslizaba entre pausas y tropiezos, y todas las posibilidades de impresionar al público estaban perdidas, pues incluso los más graves sentimientos eran recibidos sin cesar con ahogados arranques de hilaridad profana, tras la protección de un remoto respaldo de banco, como si el pobre párroco hubiera dicho algo extrañamente jocoso. La congregación se sintió muy aliviada cuando terminó la prueba y se dijo la bendición. Tom Sawyer volvió a su casa contentísimo, pensando que el servicio divino era más satisfactorio cuando intervenía en él un poco de variedad. Solo una idea destruía su contento: aceptaba que el perro jugara con su «chinche con tenazas», pero no juzgaba correcto que se lo llevase consigo."}]$lira$::jsonb,
  145
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  16,
  'Beck y Tom se encuentran (1/5)',
  $lira$[{"type": "p", "text": "El lunes por la mañana Tom Sawyer se despertó sumido en la desesperación. El lunes por la mañana lo encontraba siempre así, ya que empezaba otra semana de lento sufrimiento en la escuela. En general Tom comenzaba ese día con el deseo de que no hubiese habido ninguna fiesta intermedia, pues le resultaba mucho más odiosa la vuelta al cautiverio."}, {"type": "p", "text": "Tom reflexionaba en la cama. Se le ocurrió que hubiera deseado estar enfermo; de ese modo se habría quedado en casa. Era una vaga posibilidad. Inspeccionó su organismo. No halló dolencia alguna y volvió a investigar. Esta vez creyó descubrir síntomas de cólico y se puso a fomentarlos con extraordinarias esperanzas. Pero los síntomas se debilitaron enseguida y al cabo de poco fenecieron del todo. Volvió a sus reflexiones. De repente descubrió algo. Se le movía uno de los dientes superiores. Era una suerte; ya se disponía a iniciar los lamentos como «principio de alarma», decía él, cuando se le ocurrió que si comparecía ante el tribunal con ese argumento, su tía le arrancaría el diente y le haría daño. En consecuencia, decidió guardar el diente como reserva y buscó otra cosa. No se le ocurrió nada durante un rato, y al final recordó haber oído hablar al doctor de cierta dolencia que obligaba al paciente a guardar cama durante dos o tres semanas con el peligro de perder un dedo. El muchacho sacó ansiosamente el pie con el dedo enfermo de debajo de la sábana y lo alzó para examinarlo. Ignoraba por completo los síntomas del mal. Sin embargo, le pareció que valía la pena arriesgarse, y se puso a gemir con extraordinario ardor. Sid continuaba durmiendo como un leño."}, {"type": "p", "text": "Tom gimió con más fuerza y se imaginó que comenzaba a dolerle el pie."}, {"type": "p", "text": "Sin resultado por parte de Sid."}, {"type": "p", "text": "Tom resollaba ya a causa de sus esfuerzos. Descansó un momento, tomó aliento y ejecutó una sucesión de gemidos admirables."}, {"type": "p", "text": "Sid continuaba roncando."}, {"type": "p", "text": "Tom estaba exasperado. Dijo: «¡Sid, Sid!», y lo sacudió. Este procedimiento dio resultado, y Tom comenzó a gemir de nuevo. Sid bostezó, se desperezó, luego se incorporó sobre el codo con un bufido y empezó a mirar fijamente a Tom. Este continuó gimiendo."}, {"type": "p", "text": "—¡Tom! ¡Oye, Tom! —Ninguna respuesta—. ¡Oye, Tom! ¡Tom! ¿Qué te ocurre, Tom? —dijo Sid sacudiéndolo y mirándole el rostro ansiosamente."}, {"type": "p", "text": "Tom se lamentó."}, {"type": "p", "text": "—Ay, no, Sid. No me empujes así."}, {"type": "p", "text": "—Pero ¿qué te ocurre, Tom? Llamaré a la tía Polly."}, {"type": "p", "text": "—No… no tiene importancia. Puede que se me pase dentro de poco. No llames a nadie."}, {"type": "p", "text": "—¡Tengo que llamarla! No grites así, Tom, es horrible. ¿Cuánto tiempo llevas así?"}, {"type": "p", "text": "—Horas. ¡Uy! No me sacudas así, Sid, me matarás."}, {"type": "p", "text": "—Tom, ¿por qué no me has despertado antes? Ay, Tom, no. Se me pone la piel de gallina al oírte. Tom, ¿qué te pasa?"}, {"type": "p", "text": "—Te lo perdono todo, Sid. —Gemido—. Todo lo que me has hecho. Cuando ya no esté aquí… —Ay, Tom, no irás a morirte, ¿verdad? Ay, no, Tom, no. Acaso…"}, {"type": "p", "text": "—Los perdono a todos, Sid. —Gemido—. Díselo, Sid. Oye, Sid, dale mi bastidor de ventana y mi gato bizco a la chica nueva que ha venido al pueblo y dile…"}, {"type": "p", "text": "Pero Sid había cogido su ropa al vuelo y había salido. Tom estaba sufriendo de veras, a consecuencia del magnífico trabajo de su imaginación, de modo que sus lamentos habían adquirido un tono de verdadera autenticidad."}, {"type": "p", "text": "Sid voló escaleras abajo y dijo:"}, {"type": "p", "text": "—Tía Polly, venga usted. Tom se está muriendo."}, {"type": "p", "text": "—¡Muriendo!"}, {"type": "p", "text": "—Sí, señora. No pierda tiempo y venga enseguida."}, {"type": "p", "text": "—¡Qué disparate! No lo creo."}, {"type": "p", "text": "Pero, con todo, subió a toda prisa la escalera con Sid y Mary pisándole los talones. Y tenía la cara pálida y le temblaban los labios. Al llegar junto al lecho dijo sofocada:"}, {"type": "p", "text": "—¡Tom! Tom, ¿qué te sucede?"}, {"type": "p", "text": "—Ay, tita, estoy…"}, {"type": "p", "text": "—¿Qué te ocurre, qué es lo que te pasa, hijo?"}, {"type": "p", "text": "—Ay, tita, el dedo del pie que me está doliendo mucho."}, {"type": "p", "text": "La anciana se dejó caer sobre una silla y se rio un poco, lloró otro poco y luego hizo ambas cosas a la vez. Eso la serenó y dijo:"}, {"type": "p", "text": "—Tom, ¡qué susto me has dado! Ahora basta de tonterías y levántate de la cama."}, {"type": "p", "text": "Los lamentos cesaron y el dolor desapareció del dedo herido. El muchacho se sintió en ridículo y dijo:"}, {"type": "p", "text": "—Tía Polly, parecía dolorido, y me hacía tanto daño que ni siquiera me acordaba del diente."}]$lira$::jsonb,
  732
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  17,
  'Beck y Tom se encuentran (2/5)',
  $lira$[{"type": "p", "text": "—¿El diente? ¡Vaya, vaya! ¿Qué diente?"}, {"type": "p", "text": "—Uno que se mueve, y me duele horrores."}, {"type": "p", "text": "—Bueno, veámoslo, y no vuelvas otra vez con los lamentos. Abre la boca. Bien, el diente se mueve, pero no vas a morirte por eso. Mary, tráeme un hilo de seda y una brasa de la cocina."}, {"type": "p", "text": "—Por favor, tía, no me lo arranque —exclamó Tom—. Ya no me duele. De veras que no. Por favor, tía. Ya no quiero quedarme en casa para no ir a la escuela."}, {"type": "p", "text": "—Ah, vamos, ¿conque ya no quieres? ¿Así que todo este alboroto solo era para quedarte en casa y poder ir de pesca en vez de ir a la escuela? Tom, Tom, te quiero mucho y parece que tú solo procuras por todos los medios herir mi viejo corazón con tus afrentas."}, {"type": "p", "text": "Entretanto, el instrumental dentario ya estaba dispuesto. La anciana ató con fuerza un extremo del hilo de seda al diente de Tom y anudó el otro extremo a un poste del lecho. Entonces cogió la brasa y de pronto la arrojó a la cara del muchacho. Un instante después el diente colgaba balanceándose del poste de la cama."}, {"type": "p", "text": "Pero todas las desgracias tienen sus compensaciones. Al encaminarse Tom a la escuela, después del desayuno, fue la envidia de todos los muchachos que se encontró, porque el boquete en la hilera superior de sus dientes le permitía escupir en un estilo nuevo y admirable. Reunió un cortejo de muchachos interesados en la exhibición, y uno de ellos, que se había cortado un dedo y había sido objeto de fascinación y de homenaje hasta aquel momento, de repente se encontró sin partidarios y despojado de su gloria. Estaba apesadumbrado y dijo con un desprecio que no sentía que escupir como Tom Sawyer no tenía importancia; pero otro rapaz exclamó: «… dice que son verdes», y tuvo que desaparecer, héroe desencumbrado."}, {"type": "p", "text": "Poco después se tropezó con el joven paria del pueblo, Huckleberry Finn, el hijo del borracho local. Huckleberry era cordialmente odiado y temido por todas las madres del pueblo, porque era vago, ordinario y malo, vivía al margen de la ley, y todos sus hijos lo admiraban, disfrutaban de su compañía prohibida y deseaban atreverse a ser como él. Tom era como el resto de los chicos respetables en lo de envidiar a Huckleberry su deslumbrante condición de proscrito, y había recibido órdenes estrictas de no jugar con él. En consecuencia, jugaba con él cada vez que tenía oportunidad. Huckleberry siempre vestía ropa vieja de hombres adultos, la cual estaba en perenne floración y revoloteo de andrajos. Su sombrero era una vasta ruina con un solo pedazo de ala en forma de media luna; su chaqueta, cuando la llevaba, le colgaba casi hasta los talones y los botones posteriores le llegaban hasta mucho más abajo de la espalda; solo un tirante le aguantaba los pantalones, cuyo trasero formaba una bolsa muy baja que nada contenía, y las perneras terminadas en flecos se arrastraban por el barro si no estaban arremangadas. Huckleberry iba y venía a su libre antojo. Dormía al pie de las puertas cuando hacía buen tiempo, y en barriles vacíos si llovía; no tenía que ir a la escuela ni a la iglesia, ni soportar a ningún maestro ni obedecer a nadie; podía ir a pescar o a nadar cuando y a donde le viniese en gana, y quedarse allí el tiempo que le apeteciera; nadie le prohibía pelearse; podía tardar en acostarse el tiempo que gustara; siempre era el primer muchacho que iba descalzo en primavera y el último en calzar zapatos en otoño; nunca tenía que lavarse ni ponerse ropa limpia y podía jurar con una maravillosa libertad. En una palabra: el muchacho tenía todo cuanto da valor a la vida. Eso pensaba cualquier chico acosado, aprisionado y respetable de San Petersburgo."}, {"type": "p", "text": "Tom saludó al romántico proscrito."}, {"type": "p", "text": "—Hola, Huckleberry."}, {"type": "p", "text": "—Hola, chico. ¿Qué te parece esto?"}, {"type": "p", "text": "—¿Qué llevas ahí?"}, {"type": "p", "text": "—Un gato muerto."}, {"type": "p", "text": "—Déjamelo ver, Huck. ¡Caracoles, qué tieso está! ¿Dónde lo has encontrado?"}, {"type": "p", "text": "—Se lo compré a un chico."}, {"type": "p", "text": "—¿A cambio de qué?"}, {"type": "p", "text": "—De un billete azul y una vejiga que encontré en el matadero."}, {"type": "p", "text": "—¿Dónde encontraste el billete azul?"}, {"type": "p", "text": "—Se lo cambié a Ben Rogers hace dos semanas por un aro de hierro."}, {"type": "p", "text": "—Oye, Huck, ¿tú sabes para qué sirven los gatos muertos?"}, {"type": "p", "text": "—¿Para qué? Curan las verrugas."}]$lira$::jsonb,
  724
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  18,
  'Beck y Tom se encuentran (3/5)',
  $lira$[{"type": "p", "text": "—¿De veras? Yo sé algo mejor."}, {"type": "p", "text": "—Apuesto a que no. ¿Qué es?"}, {"type": "p", "text": "—Agua de yesca."}, {"type": "p", "text": "—¡Agua de yesca! Yo no daría nada por el agua de yesca."}, {"type": "p", "text": "—Conque no, ¿eh? ¿La has probado alguna vez?"}, {"type": "p", "text": "—No, yo no. Pero Bob Tanner sí."}, {"type": "p", "text": "—¿Quién te lo ha dicho?"}, {"type": "p", "text": "—Pues él se lo contó a Jeff Thatcher y Jeff se lo dijo a Johnny Baker, y Johnny se lo dijo a Jim Hollis, y Jim se lo dijo a Ben Rogers, y Ben se lo contó a un negro, y el negro me lo contó a mí. ¿Qué dices ahora?"}, {"type": "p", "text": "—Bien, ¿y qué? Todos han mentido. Al menos todos excepto el negro. No lo conozco. Pero nunca he visto a un negro que no mintiese. Pero aunque no lo creo, dime cómo lo hizo Bob Tanner, Huck."}, {"type": "p", "text": "—Pues metió la mano en un tronco podrido que contenía agua de lluvia."}, {"type": "p", "text": "—¿De día?"}, {"type": "p", "text": "—Por supuesto."}, {"type": "p", "text": "—¿De cara al tronco?"}, {"type": "p", "text": "—Sí. Al menos, lo entendí así."}, {"type": "p", "text": "—¿Dijo algo?"}, {"type": "p", "text": "—No lo creo, no sé."}, {"type": "p", "text": "—¿Ves? ¿Cómo es posible hablar de la cura de verrugas con agua de yesca de un modo tan disparatado? Claro que así no dio resultado. Tienes que adentrarte tú mismo en el bosque, hasta algún lugar donde sepas que hay un tronco con agua de yesca, y a las doce en punto de la noche apoyas la espalda contra el tronco, metes la mano y dices: «Grano de cebada, grano de cebada, cómase el indio el salvado; agua de yesca, agua de yesca, las verrugas me ha curado», y entonces te alejas deprisa once pasos, con los ojos cerrados, y luego te vuelves tres veces y regresas a casa sin cruzar ni una sola palabra con nadie. Porque si hablas el hechizo se desvanece."}, {"type": "p", "text": "—Bien, parece un buen sistema; pero Bob Tanner no lo hizo así."}, {"type": "p", "text": "—Claro que no, puedes estar seguro, porque es el chico más plagado de verrugas del pueblo; y no tendría ni una si supiera cómo utilizar el agua de yesca. Así me he sacado yo de las manos miles de verrugas, Huck. Juego tan a menudo con las ranas que siempre me sale una cantidad enorme de verrugas. A veces me las saco con un haba."}, {"type": "p", "text": "—Sí, las habas son buenas. Ese remedio lo conozco."}, {"type": "p", "text": "—¿De veras? ¿Y cómo lo haces?"}, {"type": "p", "text": "—Coges el haba y la partes, y cortas la verruga procurando que salga un poquitín de sangre, y entonces pones la sangre en un pedazo del haba y cavas un agujero y la entierras a medianoche en una encrucijada cuando no haya luna, y luego quemas el resto del haba. ¿Comprendes? El trozo que tiene la sangre irá chupando sin cesar para atraer así el otro pedazo, lo cual ayuda a la sangre a chupar la verruga y esta desaparece muy pronto."}, {"type": "p", "text": "—Exacto, Huck, así es; aunque si al enterrar el trozo dices: «Adentro, haba; afuera, verruga; a fastidiarme no vuelvas nunca», es mejor. Así lo hace Joe Harper, y ha estado cerca de Coonvilie y en muchos sitios. Pero, dime: ¿cómo las curas con gatos muertos?"}, {"type": "p", "text": "—Mira, coges el gato y te vas al cementerio poco antes de medianoche, cuando hayan enterrado a alguien que haya sido un granuja; y a medianoche vendrá un demonio, o quizá dos o tres, pero tú no los puedes ver, solo oyes algo parecido al viento, o tal vez los oigas hablar; y cuando se estén llevando al fulano, arrojas el gato detrás de ellos y dices: «El demonio sigue al muerto, el gato sigue al demonio, las verrugas siguen al gato, y yo me quedo sin ellas». Eso se lleva cualquier verruga."}, {"type": "p", "text": "—Parece eficaz. ¿Lo has probado alguna vez, Huck?"}, {"type": "p", "text": "—No, pero me lo dijo la vieja Hopkins."}, {"type": "p", "text": "—Debe de ser verdad, porque dicen que es bruja."}, {"type": "p", "text": "—¡Dicen! Vamos, Tom, yo sé que lo es. Ella embrujó a papá. El propio papá lo dice. Un día que él pasaba por ahí, vio que ella lo estaba embrujando, así que cogió una piedra y, si ella no se hubiera apartado, le habría dado en la cabeza. Pues bien: aquella misma noche se cayó de un cobertizo donde yacía borracho y se rompió un brazo."}, {"type": "p", "text": "—¡Es terrible! ¿Cómo supo él que lo estaba embrujando?"}, {"type": "p", "text": "—¡Válgame el cielo! Papá te lo contaría mejor. Dice que cuando alguien te mira muy fijo, es que te está embrujando, sobre todo si cuchichea algo. Porque al cuchichear está diciendo el padrenuestro al revés."}]$lira$::jsonb,
  740
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  19,
  'Beck y Tom se encuentran (4/5)',
  $lira$[{"type": "p", "text": "—Oye, Huck, ¿cuándo irás a probar el gato?"}, {"type": "p", "text": "—Esta noche. Calculo que esta noche vendrán por el viejo Hoss Williams."}, {"type": "p", "text": "—Pero si lo enterraron el sábado. ¿No crees que se lo llevarían el mismo sábado por la noche?"}, {"type": "p", "text": "—¡Qué tonterías dices! ¿Cómo iban a tener poder antes de medianoche? Y entonces ya es domingo. No creo que a los demonios les guste trabajar en domingo."}, {"type": "p", "text": "—Nunca lo había pensado. Debe de ser así. ¿Me dejas ir contigo?"}, {"type": "p", "text": "—Por supuesto, si no tienes miedo."}, {"type": "p", "text": "—¡Miedo! Lo dudo. ¿Maullarás?"}, {"type": "p", "text": "—Sí, y tú contesta si puedes. La última vez me tuviste maullando no sé yo cuánto rato, hasta que la vieja Hays comenzó a tirarme piedras y a decir: «¡Diantre de gato!», así que le arrojé un ladrillo por la ventana, pero no se lo digas."}, {"type": "p", "text": "—No se lo diré. Aquella noche no pude maullar, porque mi tía me vigilaba, pero esta vez sí que lo haré. Dime, ¿qué es eso que tienes?"}, {"type": "p", "text": "—No es más que una garrapata."}, {"type": "p", "text": "—¿Dónde la has cogido?"}, {"type": "p", "text": "—En el bosque."}, {"type": "p", "text": "—¿Qué quieres por ella?"}, {"type": "p", "text": "—No sé. No quiero venderla."}, {"type": "p", "text": "—Muy bien. Al fin y al cabo, es una garrapata pequeñísima."}, {"type": "p", "text": "—Cualquiera puede despreciar una garrapata que no es suya. A mí me gusta. Es una garrapata bastante buena para mí."}, {"type": "p", "text": "—Pero ¡si hay muchísimas garrapatas! Yo podría tener miles, si quisiera."}, {"type": "p", "text": "—¿Y por qué no tienes? Porque sabes muy bien que no puedes. Esta es la primera garrapata que he visto este año."}, {"type": "p", "text": "—Oye, Huck, te doy mi diente por ella."}, {"type": "p", "text": "—A ver."}, {"type": "p", "text": "Tom sacó un trocito de papel y lo desdobló con cuidado. Huckleberry lo miró codiciosamente. La tentación era fortísima. Al fin dijo:"}, {"type": "p", "text": "—¿Es de verdad?"}, {"type": "p", "text": "Tom alzó el labio superior y le enseñó el hueco."}, {"type": "p", "text": "—Muy bien —dijo Huckleberry—, pues, por mí, trato hecho."}, {"type": "p", "text": "Tom encerró la garrapata en la caja de cápsulas que hasta poco antes había sido la prisión del «chinche con tenazas», y los dos muchachos se separaron, sintiéndose más ricos que antes."}, {"type": "p", "text": "Cuando Tom llegó al pequeño edificio aislado de la escuela, entró a toda prisa, como si hubiese ido con diligente celo. Colgó el sombrero en la percha y se encaminó a su sitio con afanosa actividad. El maestro, entronizado en las alturas, en su holgado sillón desfondado, dormitaba arrullado por el zumbido soporífero de la clase. La interrupción lo despabiló."}, {"type": "p", "text": "—¡Thomas Sawyer!"}, {"type": "p", "text": "Tom sabía que cuando el maestro pronunciaba su nombre completo se avecinaba una tormenta."}, {"type": "p", "text": "—Señor."}, {"type": "p", "text": "—Venga aquí. ¿Por qué vuelve usted a llegar tarde, como de costumbre?"}, {"type": "p", "text": "Tom se disponía a ampararse en una mentira, cuando vio dos largas trenzas de cabellos dorados que pendían a lo largo de una espalda que reconoció en virtud de la eléctrica simpatía del amor; y junto a esa personilla había el único sitio libre de la parte de las chicas. Al punto dijo:"}, {"type": "h", "text": "—¡Me He Detenido A Charlar Con Huckleberry Finn!"}, {"type": "p", "text": "El pulso del maestro se paralizó; los ojos se le abrieron desmesuradamente. Cesó el zumbido de la clase. Los alumnos se preguntaban si aquel insensato muchacho había perdido el juicio."}, {"type": "p", "text": "—¿Qué… qué ha hecho usted? —balbució el maestro."}, {"type": "p", "text": "—Me he detenido a charlar con Huckleberry Finn."}, {"type": "p", "text": "Las palabras no habían sido interpretadas de manera errónea."}, {"type": "p", "text": "—Thomas Sawyer, esta es la confesión más sorprendente que he oído en mi vida. La simple palmeta no es suficiente para tal ofensa. Sáquese la chaqueta."}, {"type": "p", "text": "El brazo del maestro actuó hasta cansarse y la provisión de varas disminuyó notablemente. Luego siguió esta orden:"}, {"type": "p", "text": "—Ahora, señor, vaya usted a sentarse con las chicas. Y que esto le sirva de escarmiento. Las risitas que resonaron por toda la sala parecieron avergonzar al muchacho, pero, en realidad, su rubor era causado más bien por el respetuoso pavor hacia el desconocido ídolo y el temeroso placer que le proporcionaba su buena fortuna. Tom se sentó a un extremo del banco de pino y la muchacha se apartó con un saltito y un brusco movimiento de cabeza. Codazos, guiños y murmullos atravesaron la clase, pero Tom estaba inmóvil, con los brazos sobre el largo y ancho pupitre, fingiendo estudiar su libro. Al cabo de poco dejaron de prestarle atención, y el acostumbrado zumbido invadió una vez más la soñolienta atmósfera. Entonces el muchacho comenzó a lanzar miradas furtivas a la niña. Esta lo notó, le sacó la lengua y le ofreció el reverso de la cabeza durante un minuto. Cuando volvió el rostro de nuevo con cautela, descubrió un melocotón delante de ella. Lo apartó de un manotazo. Tom lo colocó otra vez en su sitio. Ella lo rechazó de nuevo pero con menos fuerza. Tom, paciente, volvió a colocarlo en su lugar. Entonces ella dejó que se quedara allí. Tom garrapateó en su pizarra: «Por favor, tómalo; tengo más». La muchacha dio una ojeada al escrito, pero no hizo señal ninguna. Luego el muchacho comenzó a dibujar algo en la pizarra, ocultando su obra con la mano izquierda. Durante algún tiempo la muchacha pretendió no darse cuenta; pero su humana curiosidad empezó a manifestarse con señales apenas perceptibles. El muchacho seguía dibujando, absorto en apariencia. La chica hizo una especie de intento poco comprometedor de verlo, pero Tom no demostró que lo hubiera observado. Al final la niña se rindió y musitó vacilante:"}]$lira$::jsonb,
  877
);
